struct BufferState {
  std::vector<unsigned char> bytes;
};

constexpr uint64_t kMaximumManagedStreamBytes = 64ULL * 1024ULL * 1024ULL;
constexpr size_t kMaximumManagedFrameCount = 65536;

bool ResolveManagedStreamPosition(int64_t offset, int whence, uint64_t current,
                                  uint64_t end, uint64_t maximum,
                                  uint64_t& position) {
  uint64_t base = 0;
  if (whence == LB_CEF3_STREAM_SEEK_BEGIN) base = 0;
  else if (whence == LB_CEF3_STREAM_SEEK_CURRENT) base = current;
  else if (whence == LB_CEF3_STREAM_SEEK_END) base = end;
  else return false;
  if (base > maximum) return false;
  if (offset >= 0) {
    const auto delta = static_cast<uint64_t>(offset);
    if (delta > maximum - base) return false;
    position = base + delta;
    return true;
  }
  const uint64_t magnitude = static_cast<uint64_t>(-(offset + 1)) + 1;
  if (magnitude > base) return false;
  position = base - magnitude;
  return true;
}

class BridgeReadHandler final : public CefReadHandler {
 public:
  BridgeReadHandler(std::shared_ptr<BufferState> backing_buffer, bool may_block)
      : backing_buffer_(std::move(backing_buffer)), may_block_(may_block) {}

  size_t Read(void* ptr, size_t size, size_t n) override {
    if (!ptr || size == 0 || n == 0 || n > std::numeric_limits<size_t>::max() / size) {
      return 0;
    }
    std::lock_guard<std::mutex> lock(mutex_);
    if (!backing_buffer_ || position_ > backing_buffer_->bytes.size()) return 0;
    const size_t requested = size * n;
    const size_t available = backing_buffer_->bytes.size() - position_;
    const size_t byte_count = std::min(requested, available) / size * size;
    if (byte_count == 0) return 0;
    std::copy_n(backing_buffer_->bytes.data() + position_, byte_count,
                static_cast<unsigned char*>(ptr));
    position_ += byte_count;
    return byte_count / size;
  }

  int Seek(int64_t offset, int whence) override {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!backing_buffer_) return 1;
    uint64_t next = 0;
    if (!ResolveManagedStreamPosition(offset, whence, position_, backing_buffer_->bytes.size(),
                                      backing_buffer_->bytes.size(), next)) {
      return 1;
    }
    position_ = static_cast<size_t>(next);
    return 0;
  }

  int64_t Tell() override {
    std::lock_guard<std::mutex> lock(mutex_);
    return static_cast<int64_t>(position_);
  }

  int Eof() override {
    std::lock_guard<std::mutex> lock(mutex_);
    return !backing_buffer_ || position_ >= backing_buffer_->bytes.size();
  }

  bool MayBlock() override { return may_block_; }

 private:
  std::mutex mutex_;
  std::shared_ptr<BufferState> backing_buffer_;
  size_t position_ = 0;
  const bool may_block_;
  IMPLEMENT_REFCOUNTING(BridgeReadHandler);
};

class BridgeWriteHandler final : public CefWriteHandler {
 public:
  explicit BridgeWriteHandler(bool may_block) : may_block_(may_block) {}

  size_t Write(const void* ptr, size_t size, size_t n) override {
    if (!ptr || size == 0 || n == 0 || n > std::numeric_limits<size_t>::max() / size) {
      return 0;
    }
    const size_t byte_count = size * n;
    std::lock_guard<std::mutex> lock(mutex_);
    if (position_ > kMaximumManagedStreamBytes
        || byte_count > kMaximumManagedStreamBytes - position_) {
      return 0;
    }
    const size_t next_size = position_ + byte_count;
    try {
      if (next_size > bytes_.size()) bytes_.resize(next_size, 0);
    } catch (...) {
      return 0;
    }
    std::copy_n(static_cast<const unsigned char*>(ptr), byte_count, bytes_.data() + position_);
    position_ = next_size;
    return n;
  }

  int Seek(int64_t offset, int whence) override {
    std::lock_guard<std::mutex> lock(mutex_);
    uint64_t next = 0;
    if (!ResolveManagedStreamPosition(offset, whence, position_, bytes_.size(),
                                      kMaximumManagedStreamBytes, next)) {
      return 1;
    }
    position_ = static_cast<size_t>(next);
    return 0;
  }

  int64_t Tell() override {
    std::lock_guard<std::mutex> lock(mutex_);
    return static_cast<int64_t>(position_);
  }

  int Flush() override { return 0; }
  bool MayBlock() override { return may_block_; }

  std::vector<unsigned char> CopyBytes() {
    std::lock_guard<std::mutex> lock(mutex_);
    return bytes_;
  }

 private:
  std::mutex mutex_;
  std::vector<unsigned char> bytes_;
  size_t position_ = 0;
  const bool may_block_;
  IMPLEMENT_REFCOUNTING(BridgeWriteHandler);
};

