struct ContinuationState {
  std::mutex mutex;
  std::chrono::steady_clock::time_point deadline;
  CefRefPtr<CefTaskRunner> task_runner;
  // CefTaskRunner::GetForCurrentThread() can be null for CEF's UI thread
  // with multi_threaded_message_loop enabled. Retain the originating CEF
  // thread as a safe dispatch fallback instead of ever invoking an official
  // continuation from the timer thread.
  int origin_thread_id = -1;
  std::function<void(int, const std::wstring&)> complete;
  int default_action = 0;
  LB_CEF3_CONTINUATION_HANDLE handle = 0;
  bool finished = false;
  bool client_certificate_selection = false;
  std::vector<CefRefPtr<CefX509Certificate>> client_certificates;
  int resource_callback_kind = 0;
  int64_t resource_callback_minimum = 0;
  int64_t resource_callback_maximum = 0;
  std::shared_ptr<std::atomic<int64_t>> resource_callback_value;
};

