template <typename T>
std::shared_ptr<T> GetObject(LB_CEF3_HANDLE handle, int expected_type, int& status) {
  HandleEntry entry;
  if (!GetEntry(handle, expected_type, entry, status) || !entry.object) return {};
  return std::static_pointer_cast<T>(entry.object);
}

std::shared_ptr<ValueState> GetValueState(LB_CEF3_HANDLE handle, int& status) {
  return GetObject<ValueState>(handle, LB_CEF3_HANDLE_VALUE, status);
}

std::shared_ptr<DictionaryState> GetDictionaryState(LB_CEF3_HANDLE handle, int& status) {
  return GetObject<DictionaryState>(handle, LB_CEF3_HANDLE_DICTIONARY, status);
}

std::shared_ptr<ListState> GetListState(LB_CEF3_HANDLE handle, int& status) {
  return GetObject<ListState>(handle, LB_CEF3_HANDLE_LIST, status);
}

std::shared_ptr<FrameState> GetFrameState(LB_CEF3_HANDLE handle, int& status) {
  auto state = GetObject<FrameState>(handle, LB_CEF3_HANDLE_FRAME, status);
  if (!state) return {};
  auto browser = state->browser.lock();
  if (!browser) {
    status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"Frame所属浏览器已经释放");
    return {};
  }
  std::lock_guard<std::mutex> lock(browser->mutex);
  std::lock_guard<std::mutex> frame_lock(state->mutex);
  if (browser->closed || !browser->browser || !state->frame) {
    status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"Frame所属浏览器已经关闭");
    return {};
  }
  status = LB_CEF3_OK;
  return state;
}

std::shared_ptr<DomDocumentState> GetDomDocumentState(
    LB_CEF3_HANDLE handle, int& status) {
  auto state = GetObject<DomDocumentState>(
      handle, LB_CEF3_HANDLE_DOM_DOCUMENT, status);
  if (!state || !state->snapshot) return {};
  return state;
}

std::shared_ptr<DomNodeState> GetDomNodeState(
    LB_CEF3_HANDLE handle, int& status) {
  auto state = GetObject<DomNodeState>(handle, LB_CEF3_HANDLE_DOM_NODE, status);
  if (!state || !state->snapshot) return {};
  std::lock_guard<std::mutex> lock(state->snapshot->mutex);
  if (state->index < 0
      || static_cast<size_t>(state->index) >= state->snapshot->nodes.size()) {
    status = Fail(
        LB_CEF3_ERROR_RELEASED_HANDLE,
        L"DOM节点快照已经失效");
    return {};
  }
  return state;
}

bool IsV8ProxyHandleType(int32_t type) {
  switch (type) {
    case LB_CEF3_HANDLE_V8_CONTEXT:
    case LB_CEF3_HANDLE_V8_VALUE:
    case LB_CEF3_HANDLE_V8_EXCEPTION:
    case LB_CEF3_HANDLE_V8_STACK_TRACE:
    case LB_CEF3_HANDLE_V8_STACK_FRAME:
    case LB_CEF3_HANDLE_V8_BACKING_STORE:
    case LB_CEF3_HANDLE_V8_ACCESSOR:
    case LB_CEF3_HANDLE_V8_INTERCEPTOR:
    case LB_CEF3_HANDLE_V8_ARRAY_BUFFER_RELEASE_CALLBACK:
    case LB_CEF3_HANDLE_V8_HANDLER:
    case LB_CEF3_HANDLE_V8_TASK_RUNNER:
      return true;
    default:
      return false;
  }
}

std::shared_ptr<V8ProxyState> GetV8ProxyState(
    LB_CEF3_HANDLE handle, int32_t expected_type, int& status) {
  HandleEntry entry;
  if (!GetEntry(handle, expected_type, entry, status) || !entry.object) return {};
  if (!IsV8ProxyHandleType(entry.type)) {
    status = Fail(LB_CEF3_ERROR_HANDLE_TYPE, L"句柄不是受管renderer V8对象");
    return {};
  }
  auto state = std::static_pointer_cast<V8ProxyState>(entry.object);
  if (!state || !state->valid.load(std::memory_order_acquire)) {
    status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"renderer V8对象租约已经失效");
    return {};
  }
  auto browser = state->browser.lock();
  if (!browser) {
    status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"renderer V8对象所属浏览器已经释放");
    return {};
  }
  {
    std::lock_guard<std::mutex> lock(browser->mutex);
    if (browser->closed || !browser->browser) {
      status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"renderer V8对象所属浏览器已经关闭");
      return {};
    }
  }
  status = LB_CEF3_OK;
  return state;
}

LB_CEF3_HANDLE RegisterV8Proxy(
    const std::shared_ptr<V8ProxyState>& state, int32_t type) {
  if (!state || !IsV8ProxyHandleType(type) || state->renderer_id == 0
      || state->renderer_id > kMaximumRendererLeaseId) {
    Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"renderer V8对象描述无效");
    return 0;
  }
  state->handle_type = type;
  HandleEntry entry;
  entry.type = type;
  entry.object = state;
  return Register(std::move(entry));
}

