LB_CEF3_HANDLE RegisterStreamReader(CefRefPtr<CefStreamReader> reader,
                                    std::shared_ptr<BufferState> backing_buffer) {
  if (!reader) {
    Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF读取流创建失败");
    return 0;
  }
  auto state = std::make_shared<StreamReaderState>();
  state->reader = std::move(reader);
  state->backing_buffer = std::move(backing_buffer);
  HandleEntry entry;
  entry.type = LB_CEF3_HANDLE_STREAM;
  entry.object = std::move(state);
  return Register(std::move(entry));
}

