void ReleaseJsHookHandlesForBrowser(const std::shared_ptr<BrowserState>& browser) {
  std::lock_guard<std::mutex> lock(g_mutex);
  for (auto iterator = g_handles.begin(); iterator != g_handles.end();) {
    if (iterator->second.type != LB_CEF3_HANDLE_JSHOOK || !iterator->second.object) {
      ++iterator;
      continue;
    }
    auto hook = std::static_pointer_cast<JsHookHandleState>(iterator->second.object);
    auto owner = hook->browser.lock();
    if (owner && owner == browser) iterator = g_handles.erase(iterator);
    else ++iterator;
  }
}

void ReleaseFrameHandlesForBrowser(const std::shared_ptr<BrowserState>& browser) {
  std::vector<HandleEntry> released;
  {
    std::lock_guard<std::mutex> lock(g_mutex);
    for (auto iterator = g_handles.begin(); iterator != g_handles.end();) {
      if (iterator->second.type != LB_CEF3_HANDLE_FRAME || !iterator->second.object) {
        ++iterator;
        continue;
      }
      auto frame = std::static_pointer_cast<FrameState>(iterator->second.object);
      auto owner = frame->browser.lock();
      if (owner && owner == browser) {
        released.push_back(std::move(iterator->second));
        iterator = g_handles.erase(iterator);
      } else {
        ++iterator;
      }
    }
  }
  released.clear();
}

void ReleaseV8HandlesForBrowser(const std::shared_ptr<BrowserState>& browser) {
  std::vector<HandleEntry> released;
  {
    std::lock_guard<std::mutex> lock(g_mutex);
    for (auto iterator = g_handles.begin(); iterator != g_handles.end();) {
      if ((iterator->second.type != LB_CEF3_HANDLE_V8_VALUE_COLLECTION
           && !IsV8ProxyHandleType(iterator->second.type))
          || !iterator->second.object) {
        ++iterator;
        continue;
      }
      std::shared_ptr<BrowserState> owner;
      std::shared_ptr<V8ProxyState> state;
      if (iterator->second.type == LB_CEF3_HANDLE_V8_VALUE_COLLECTION) {
        owner = std::static_pointer_cast<V8ValueCollectionState>(
            iterator->second.object)->browser.lock();
      } else {
        state = std::static_pointer_cast<V8ProxyState>(iterator->second.object);
        owner = state->browser.lock();
      }
      if (owner && owner == browser) {
        if (state) state->valid.store(false, std::memory_order_release);
        released.push_back(std::move(iterator->second));
        iterator = g_handles.erase(iterator);
      } else {
        ++iterator;
      }
    }
  }
  released.clear();
}

void RequestServerShutdown(const std::shared_ptr<ServerState>& state) {
  if (!state) return;
  CefRefPtr<CefServer> server;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (state->shutdown_requested || state->destroyed || !state->server) return;
    state->shutdown_requested = true;
    server = state->server;
  }
  server->Shutdown();
}

bool IsCefBackedHandleType(int type) {
  switch (type) {
    case LB_CEF3_HANDLE_VALUE:
    case LB_CEF3_HANDLE_DICTIONARY:
    case LB_CEF3_HANDLE_LIST:
    case LB_CEF3_HANDLE_IMAGE:
    case LB_CEF3_HANDLE_MENU:
    case LB_CEF3_HANDLE_CERTIFICATE:
    case LB_CEF3_HANDLE_NAVIGATION_ENTRY:
    case LB_CEF3_HANDLE_REQUEST_CONTEXT:
    case LB_CEF3_HANDLE_REQUEST:
    case LB_CEF3_HANDLE_RESPONSE:
    case LB_CEF3_HANDLE_FRAME:
    case LB_CEF3_HANDLE_CERTIFICATE_PRINCIPAL:
    case LB_CEF3_HANDLE_CONTINUATION:
    case LB_CEF3_HANDLE_POST_DATA:
    case LB_CEF3_HANDLE_POST_DATA_ELEMENT:
    case LB_CEF3_HANDLE_URL_REQUEST:
    case LB_CEF3_HANDLE_PRINT_SETTINGS:
    case LB_CEF3_HANDLE_V8_CONTEXT:
    case LB_CEF3_HANDLE_V8_VALUE:
    case LB_CEF3_HANDLE_V8_EXCEPTION:
    case LB_CEF3_HANDLE_V8_STACK_TRACE:
    case LB_CEF3_HANDLE_V8_STACK_FRAME:
    case LB_CEF3_HANDLE_V8_BACKING_STORE:
    case LB_CEF3_HANDLE_V8_ACCESSOR:
    case LB_CEF3_HANDLE_V8_INTERCEPTOR:
    case LB_CEF3_HANDLE_V8_ARRAY_BUFFER_RELEASE_CALLBACK:
    case LB_CEF3_HANDLE_V8_HANDLER:
    case LB_CEF3_HANDLE_V8_TASK_RUNNER:
    case LB_CEF3_HANDLE_V8_VALUE_COLLECTION:
    case LB_CEF3_HANDLE_VIEW:
    case LB_CEF3_HANDLE_WINDOW:
    case LB_CEF3_HANDLE_LAYOUT:
    case LB_CEF3_HANDLE_OVERLAY:
    case LB_CEF3_HANDLE_SSL_STATUS:
    case LB_CEF3_HANDLE_SSL_INFO:
    case LB_CEF3_HANDLE_OSR_SURFACE:
    case LB_CEF3_HANDLE_STREAM:
    case LB_CEF3_HANDLE_COMMAND_LINE:
    case LB_CEF3_HANDLE_COMPONENT_UPDATER:
    case LB_CEF3_HANDLE_PROCESS_MESSAGE:
    case LB_CEF3_HANDLE_SHARED_PROCESS_MESSAGE_BUILDER:
    case LB_CEF3_HANDLE_SHARED_MEMORY_REGION:
    case LB_CEF3_HANDLE_TASK_MANAGER:
    case LB_CEF3_HANDLE_WAITABLE_EVENT:
    case LB_CEF3_HANDLE_TASK_RUNNER:
    case LB_CEF3_HANDLE_COMPONENT:
    case LB_CEF3_HANDLE_THREAD:
    case LB_CEF3_HANDLE_VIEW_DELEGATE:
    case LB_CEF3_HANDLE_DRAG_DATA:
    case LB_CEF3_HANDLE_RESOURCE_BUNDLE:
    case LB_CEF3_HANDLE_CLIENT:
    case LB_CEF3_HANDLE_REQUEST_CONTEXT_HANDLER:
    case LB_CEF3_HANDLE_OBSERVER_REGISTRATION:
    case LB_CEF3_HANDLE_MEDIA_ROUTER:
    case LB_CEF3_HANDLE_MEDIA_SOURCE:
    case LB_CEF3_HANDLE_MEDIA_OBSERVER:
    case LB_CEF3_HANDLE_MEDIA_SINK_COLLECTION:
    case LB_CEF3_HANDLE_MEDIA_ROUTE_COLLECTION:
    case LB_CEF3_HANDLE_MEDIA_SINK:
    case LB_CEF3_HANDLE_MEDIA_ROUTE:
    case LB_CEF3_HANDLE_SERVER:
    case LB_CEF3_HANDLE_URL_REQUEST_CLIENT:
    case LB_CEF3_HANDLE_CERTIFICATE_COLLECTION:
    case LB_CEF3_HANDLE_MESSAGE_ROUTER:
    case LB_CEF3_HANDLE_RESOURCE_MANAGER:
    case LB_CEF3_HANDLE_STREAM_RESOURCE_HANDLER:
    case LB_CEF3_HANDLE_XML_OBJECT:
    case LB_CEF3_HANDLE_ZIP_ARCHIVE:
      return true;
    default:
      return false;
  }
}

void ReleaseCefObjectsForFinalBrowserClose() {
  // This runs on CEF's UI thread from BridgeClient::OnBeforeClose. CEF 150
  // retires that thread after the final BrowserHost closes, so release every
  // remaining CEF-backed public object while its documented thread is live.
  std::unordered_map<LB_CEF3_HANDLE, HandleEntry> released;
  {
    std::lock_guard<std::mutex> lock(g_mutex);
    for (auto iterator = g_handles.begin(); iterator != g_handles.end();) {
      const bool cef_backed_task = iterator->second.type == LB_CEF3_HANDLE_TASK
          && iterator->second.task
          && iterator->second.task->cef_backed.load(std::memory_order_acquire);
      if (!cef_backed_task && !IsCefBackedHandleType(iterator->second.type)) {
        ++iterator;
        continue;
      }
      released.emplace(iterator->first, std::move(iterator->second));
      iterator = g_handles.erase(iterator);
    }
  }
  for (const auto& [handle, entry] : released) {
    (void)handle;
    if (entry.type == LB_CEF3_HANDLE_SERVER && entry.object) {
      RequestServerShutdown(std::static_pointer_cast<ServerState>(entry.object));
    }
  }
  std::fprintf(stderr, "CEF3 final-browser release count=%zu\\n", released.size());
  released.clear();
}

const Cef3OperationDescriptorV4* FindOperationV4(LB_CEF3_OPERATION_ID operation_id) {
  const auto found = std::lower_bound(
      std::begin(kCef3OperationCatalogV4), std::end(kCef3OperationCatalogV4), operation_id,
      [](const Cef3OperationDescriptorV4& entry, LB_CEF3_OPERATION_ID value) {
        return entry.operation_id < value;
      });
  if (found != std::end(kCef3OperationCatalogV4) && found->operation_id == operation_id) return found;
  return nullptr;
}

