int RegisterFrame(const std::shared_ptr<BrowserState>& browser,
                  CefRefPtr<CefFrame> frame, LB_CEF3_HANDLE* result) {
  if (!result) return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"Frame输出参数不能为空");
  if (!frame) {
    *result = 0;
    return LB_CEF3_OK;
  }
  auto state = std::make_shared<FrameState>();
  state->browser = browser;
  state->identifier = frame->GetIdentifier().ToWString();
  state->main_frame = frame->IsMain();
  state->frame = std::move(frame);
  HandleEntry entry;
  entry.type = LB_CEF3_HANDLE_FRAME;
  entry.object = state;
  std::lock_guard<std::mutex> lock(browser->mutex);
  if (browser->closed) {
    return Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"Frame所属浏览器已经关闭");
  }
  const int retain_status = LB_CEF3_HandleRetain(browser->handle);
  if (retain_status != LB_CEF3_OK) return retain_status;
  state->browser_handle = browser->handle;
  *result = Register(std::move(entry));
  return LB_CEF3_OK;
}

