void SendHookMessageToFrame(CefRefPtr<CefFrame> frame, const wchar_t* message_name,
                            const JsHookScript* hook, bool execute_existing) {
  if (!frame) return;
  auto message = CefProcessMessage::Create(message_name);
  auto arguments = message->GetArgumentList();
  if (hook) {
    arguments->SetDouble(0, static_cast<double>(hook->id));
    arguments->SetString(1, hook->name);
    arguments->SetString(2, hook->script);
    arguments->SetString(3, hook->url_pattern);
    arguments->SetInt(4, hook->frame_scope);
    arguments->SetBool(5, execute_existing);
  }
  frame->SendProcessMessage(PID_RENDERER, message);
}

void SendHookUpdate(const std::shared_ptr<BrowserState>& state, const wchar_t* message_name,
                    const JsHookScript* hook, bool execute_existing) {
  CefRefPtr<CefBrowser> browser;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    browser = state->browser;
  }
  if (!browser) return;
  std::vector<CefString> frame_ids;
  browser->GetFrameIdentifiers(frame_ids);
  if (frame_ids.empty()) {
    SendHookMessageToFrame(browser->GetMainFrame(), message_name, hook, execute_existing);
    return;
  }
  for (const auto& frame_id : frame_ids) {
    auto frame = browser->GetFrameByIdentifier(frame_id);
    if (!frame) continue;
    if (hook && hook->frame_scope == LB_CEF3_JSHOOK_MAIN_FRAME && !frame->IsMain()) continue;
    SendHookMessageToFrame(frame, message_name, hook, execute_existing);
  }
}

void SendAllHooks(const std::shared_ptr<BrowserState>& state, bool execute_existing) {
  std::vector<JsHookScript> hooks;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    hooks = state->hooks;
  }
  for (const auto& hook : hooks) SendHookUpdate(state, L"LingBuilder.Cef3.JsHookUpsert", &hook, execute_existing);
}

