std::shared_ptr<DownloadItemState> SnapshotDownloadItem(
    CefRefPtr<CefDownloadItem> item) {
  auto snapshot = std::make_shared<DownloadItemState>();
  snapshot->valid = item && item->IsValid();
  if (!snapshot->valid) return snapshot;
  snapshot->in_progress = item->IsInProgress();
  snapshot->complete = item->IsComplete();
  snapshot->canceled = item->IsCanceled();
  snapshot->interrupted = item->IsInterrupted();
#if CEF_API_ADDED(14400)
  snapshot->paused = item->IsPaused();
#endif
  snapshot->interrupt_reason = static_cast<int32_t>(item->GetInterruptReason());
  snapshot->current_speed = item->GetCurrentSpeed();
  snapshot->percent_complete = item->GetPercentComplete();
  snapshot->total_bytes = item->GetTotalBytes();
  snapshot->received_bytes = item->GetReceivedBytes();
  snapshot->start_time = item->GetStartTime().val;
  snapshot->end_time = item->GetEndTime().val;
  snapshot->full_path = item->GetFullPath().ToWString();
  snapshot->id = item->GetId();
  snapshot->url = item->GetURL().ToWString();
  snapshot->original_url = item->GetOriginalUrl().ToWString();
  snapshot->suggested_file_name = item->GetSuggestedFileName().ToWString();
  snapshot->content_disposition = item->GetContentDisposition().ToWString();
  snapshot->mime_type = item->GetMimeType().ToWString();
  return snapshot;
}

std::shared_ptr<DownloadItemState> StoreDownloadItemSnapshot(
    const std::shared_ptr<BrowserState>& browser,
    CefRefPtr<CefDownloadItem> item,
    const CefString* suggested_name = nullptr) {
  auto snapshot = SnapshotDownloadItem(std::move(item));
  if (suggested_name && snapshot->suggested_file_name.empty()) {
    snapshot->suggested_file_name = suggested_name->ToWString();
  }
  {
    std::lock_guard<std::mutex> lock(browser->mutex);
    const auto& previous = browser->last_download_item;
    if (previous && previous->id == snapshot->id) {
      if (snapshot->full_path.empty()) snapshot->full_path = previous->full_path;
      if (snapshot->url.empty()) snapshot->url = previous->url;
      if (snapshot->original_url.empty()) snapshot->original_url = previous->original_url;
      if (snapshot->suggested_file_name.empty()) {
        snapshot->suggested_file_name = previous->suggested_file_name;
      }
      if (snapshot->content_disposition.empty()) {
        snapshot->content_disposition = previous->content_disposition;
      }
      if (snapshot->mime_type.empty()) snapshot->mime_type = previous->mime_type;
      if (snapshot->start_time == 0) snapshot->start_time = previous->start_time;
    }
    browser->last_download_item = snapshot;
  }
  browser->changed.notify_all();
  return snapshot;
}

std::wstring DownloadItemEventJson(const DownloadItemState& item) {
  return L"{\"id\":" + std::to_wstring(item.id)
      + L",\"valid\":" + (item.valid ? L"true" : L"false")
      + L",\"inProgress\":" + (item.in_progress ? L"true" : L"false")
      + L",\"complete\":" + (item.complete ? L"true" : L"false")
      + L",\"canceled\":" + (item.canceled ? L"true" : L"false")
      + L",\"interrupted\":" + (item.interrupted ? L"true" : L"false")
      + L",\"paused\":" + (item.paused ? L"true" : L"false")
      + L",\"percentComplete\":" + std::to_wstring(item.percent_complete)
      + L",\"receivedBytes\":" + std::to_wstring(item.received_bytes)
      + L",\"totalBytes\":" + std::to_wstring(item.total_bytes)
      + L",\"url\":\"" + JsonEscape(item.url) + L"\"}";
}

