  bool OnBeforeDownload(
      CefRefPtr<CefBrowser>, CefRefPtr<CefDownloadItem> download_item,
      const CefString& suggested_name,
      CefRefPtr<CefBeforeDownloadCallback> callback) override {
    auto snapshot = StoreDownloadItemSnapshot(
        state_, std::move(download_item), &suggested_name);
    if (!callback) return false;
    std::filesystem::path allowed_root;
    {
      std::lock_guard<std::mutex> lock(g_mutex);
      allowed_root = g_allowed_root;
    }
    if (allowed_root.empty()) return false;
    auto file_name = std::filesystem::path(snapshot->suggested_file_name).filename();
    if (file_name.empty() || file_name == L"." || file_name == L"..") {
      file_name = L"download-" + std::to_wstring(snapshot->id) + L".bin";
    }
    std::filesystem::path resolved;
    const auto candidate = allowed_root / file_name;
    if (!IsPathAllowed(candidate.c_str(), resolved)) return false;
    const auto fields = DownloadItemEventJson(*snapshot);
    const auto legacy_response = EmitEvent(
        state_, 124, L"下载开始前", fields, true);
    if (legacy_response.action == 2) return false;
    if (IsDownloadHandlerSubscriptionEnabled(
            state_, kDownloadHandlerBeforeDownload)
        && HasEventCallbackV4(state_)) {
      auto complete = [callback, resolved](
          int action, const std::wstring& response_json) {
        if (!callback || action == 2) return;
        std::filesystem::path destination = resolved;
        bool show_dialog = false;
        auto parsed = ParseEventResponse(response_json.c_str());
        if (parsed) {
          show_dialog = EventResponseBool(parsed, "showDialog", false);
          if (parsed->HasKey("filePath")
              && parsed->GetType("filePath") == VTYPE_STRING) {
            std::filesystem::path requested;
            const auto requested_text = parsed->GetString("filePath").ToWString();
            if (!requested_text.empty()
                && IsPathAllowed(requested_text.c_str(), requested)) {
              destination = std::move(requested);
            }
          }
        }
        callback->Continue(destination.wstring(), show_dialog);
      };
      const auto async = EmitAsyncEvent(
          state_, 124, L"cef_download_handler_t", L"on_before_download",
          L"下载开始前", fields, 5000, 1, std::move(complete));
      if (async.delivered) return true;
    }
    callback->Continue(resolved.wstring(), false);
    return true;
  }

  void OnDownloadUpdated(
      CefRefPtr<CefBrowser>, CefRefPtr<CefDownloadItem> download_item,
      CefRefPtr<CefDownloadItemCallback> callback) override {
    const auto snapshot = StoreDownloadItemSnapshot(
        state_, std::move(download_item));
    std::shared_ptr<DownloadItemCallbackState> callback_state;
    LB_CEF3_HANDLE callback_handle = 0;
    if (callback) {
      callback_state = std::make_shared<DownloadItemCallbackState>();
      callback_state->browser = state_;
      callback_state->callback = std::move(callback);
      {
        std::lock_guard<std::mutex> lock(state_->mutex);
        state_->last_download_callback = callback_state;
      }
      callback_handle = RegisterDownloadItemCallback(callback_state);
    }
    EmitDownloadHandlerNotification(
        state_, kDownloadHandlerUpdated, 125, L"on_download_updated",
        L"下载状态更新", DownloadItemEventJson(*snapshot), callback_handle);
    if (callback_handle != 0) {
      LB_CEF3_HandleRelease(callback_handle);
    }
  }

