  CefSize GetPdfPaperSize(
      CefRefPtr<CefBrowser> browser, int device_units_per_inch) override {
    if (!IsPrintHandlerSubscriptionEnabled(
            state_, kPrintHandlerPdfPaperSize)) {
      return CefSize();
    }
    const auto response = EmitNotificationEventV4(
        state_, L"cef_print_handler_t", L"get_pdf_paper_size",
        L"PDF纸张尺寸请求",
        L"{\"browserId\":"
            + std::to_wstring(browser ? browser->GetIdentifier() : 0)
            + L",\"deviceUnitsPerInch\":"
            + std::to_wstring(device_units_per_inch) + L"}",
        0, true);
    if (response.action != 1 && response.action != 3) return CefSize();
    const auto parsed = ParseEventResponse(response.response_json);
    const int width = EventResponseInt(parsed, "width", 0);
    const int height = EventResponseInt(parsed, "height", 0);
    if (width <= 0 || height <= 0) return CefSize();
    return CefSize(width, height);
  }

  bool GetRootScreenRect(
      CefRefPtr<CefBrowser> browser, CefRect& rect) override {
    HWND parent = nullptr;
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      parent = state_->parent;
    }
    RECT client_rect{};
    POINT origin{};
    bool provided = parent && IsWindow(parent)
        && GetClientRect(parent, &client_rect)
        && ClientToScreen(parent, &origin);
    if (provided) {
      rect = CefRect(
          origin.x, origin.y,
          std::max<int>(1, client_rect.right - client_rect.left),
          std::max<int>(1, client_rect.bottom - client_rect.top));
    }
    if (IsRenderHandlerSubscriptionEnabled(
            state_, kRenderHandlerRootScreenRect)) {
      const auto response = EmitNotificationEventV4(
          state_, L"cef_render_handler_t", L"get_root_screen_rect",
          L"OSR根屏幕矩形请求",
          L"{\"browserId\":"
              + std::to_wstring(browser ? browser->GetIdentifier() : 0)
              + L",\"provided\":" + (provided ? L"true" : L"false")
              + L",\"rect\":" + CefRectJson(rect) + L"}",
          0, true);
      if (response.action == 2) return false;
      if (response.action == 1 || response.action == 3) {
        ApplyManagedRect(ParseEventResponse(response.response_json), rect, true);
        provided = rect.width > 0 && rect.height > 0;
      }
    }
    return provided;
  }

  void GetViewRect(CefRefPtr<CefBrowser> browser, CefRect& rect) override {
    HWND parent = nullptr;
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      parent = state_->parent;
    }
    RECT client_rect{};
    if (parent && IsWindow(parent)) GetClientRect(parent, &client_rect);
    const int width = std::max<int>(1, static_cast<int>(client_rect.right - client_rect.left));
    const int height = std::max<int>(1, static_cast<int>(client_rect.bottom - client_rect.top));
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      state_->osr_view_width = width;
      state_->osr_view_height = height;
    }
    rect = CefRect(0, 0, width, height);
    if (IsRenderHandlerSubscriptionEnabled(state_, kRenderHandlerViewRect)) {
      const auto response = EmitNotificationEventV4(
          state_, L"cef_render_handler_t", L"get_view_rect",
          L"OSR视图矩形请求",
          L"{\"browserId\":"
              + std::to_wstring(browser ? browser->GetIdentifier() : 0)
              + L",\"rect\":" + CefRectJson(rect) + L"}",
          0, true);
      if (response.action == 1 || response.action == 3) {
        ApplyManagedRect(ParseEventResponse(response.response_json), rect, true);
      }
    }
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      state_->osr_view_width = rect.width;
      state_->osr_view_height = rect.height;
    }
  }

  bool GetScreenPoint(
      CefRefPtr<CefBrowser> browser, int view_x, int view_y,
      int& screen_x, int& screen_y) override {
    HWND parent = nullptr;
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      parent = state_->parent;
    }
    POINT point{view_x, view_y};
    bool provided = parent && IsWindow(parent) && ClientToScreen(parent, &point);
    if (provided) {
      screen_x = point.x;
      screen_y = point.y;
    }
    if (IsRenderHandlerSubscriptionEnabled(state_, kRenderHandlerScreenPoint)) {
      const auto response = EmitNotificationEventV4(
          state_, L"cef_render_handler_t", L"get_screen_point",
          L"OSR屏幕坐标请求",
          L"{\"browserId\":"
              + std::to_wstring(browser ? browser->GetIdentifier() : 0)
              + L",\"viewX\":" + std::to_wstring(view_x)
              + L",\"viewY\":" + std::to_wstring(view_y)
              + L",\"screenX\":" + std::to_wstring(screen_x)
              + L",\"screenY\":" + std::to_wstring(screen_y)
              + L",\"provided\":" + (provided ? L"true" : L"false") + L"}",
          0, true);
      if (response.action == 2) return false;
      if (response.action == 1 || response.action == 3) {
        const auto parsed = ParseEventResponse(response.response_json);
        screen_x = EventResponseInt(parsed, "screenX", screen_x);
        screen_y = EventResponseInt(parsed, "screenY", screen_y);
        provided = true;
      }
    }
    return provided;
  }

  bool GetScreenInfo(
      CefRefPtr<CefBrowser> browser, CefScreenInfo& screen_info) override {
    HWND parent = nullptr;
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      parent = state_->parent;
    }
    MONITORINFO monitor_info{};
    monitor_info.cbSize = sizeof(monitor_info);
    const HMONITOR monitor = parent && IsWindow(parent)
        ? MonitorFromWindow(parent, MONITOR_DEFAULTTONEAREST)
        : MonitorFromPoint(POINT{}, MONITOR_DEFAULTTOPRIMARY);
    bool provided = monitor && GetMonitorInfoW(monitor, &monitor_info);
    if (provided) {
      const UINT dpi = parent && IsWindow(parent) ? GetDpiForWindow(parent) : 96;
      screen_info.device_scale_factor = static_cast<float>(dpi) / 96.0f;
      screen_info.depth = 32;
      screen_info.depth_per_component = 8;
      screen_info.is_monochrome = false;
      screen_info.rect = CefRect(
          monitor_info.rcMonitor.left, monitor_info.rcMonitor.top,
          monitor_info.rcMonitor.right - monitor_info.rcMonitor.left,
          monitor_info.rcMonitor.bottom - monitor_info.rcMonitor.top);
      screen_info.available_rect = CefRect(
          monitor_info.rcWork.left, monitor_info.rcWork.top,
          monitor_info.rcWork.right - monitor_info.rcWork.left,
          monitor_info.rcWork.bottom - monitor_info.rcWork.top);
    }
    if (IsRenderHandlerSubscriptionEnabled(state_, kRenderHandlerScreenInfo)) {
      const auto response = EmitNotificationEventV4(
          state_, L"cef_render_handler_t", L"get_screen_info",
          L"OSR屏幕信息请求",
          L"{\"browserId\":"
              + std::to_wstring(browser ? browser->GetIdentifier() : 0)
              + L",\"provided\":" + (provided ? L"true" : L"false")
              + L",\"deviceScaleFactor\":"
              + std::to_wstring(screen_info.device_scale_factor)
              + L",\"depth\":" + std::to_wstring(screen_info.depth)
              + L",\"depthPerComponent\":"
              + std::to_wstring(screen_info.depth_per_component)
              + L",\"monochrome\":"
              + (screen_info.is_monochrome ? L"true" : L"false")
              + L",\"rect\":" + CefRectJson(screen_info.rect)
              + L",\"availableRect\":"
              + CefRectJson(screen_info.available_rect) + L"}",
          0, true);
      if (response.action == 2) return false;
      if (response.action == 1 || response.action == 3) {
        const auto parsed = ParseEventResponse(response.response_json);
        const double scale = EventResponseDouble(
            parsed, "deviceScaleFactor", screen_info.device_scale_factor);
        if (std::isfinite(scale) && scale > 0.0 && scale <= 16.0) {
          screen_info.device_scale_factor = static_cast<float>(scale);
        }
        screen_info.depth = std::max(1, EventResponseInt(
            parsed, "depth", screen_info.depth));
        screen_info.depth_per_component = std::max(1, EventResponseInt(
            parsed, "depthPerComponent", screen_info.depth_per_component));
        screen_info.is_monochrome = EventResponseInt(
            parsed, "monochrome", screen_info.is_monochrome ? 1 : 0) != 0;
        provided = true;
      }
    }
    return provided;
  }

