  bool StartDragging(
      CefRefPtr<CefBrowser> browser, CefRefPtr<CefDragData> drag_data,
      CefRenderHandler::DragOperationsMask allowed_ops, int x, int y) override {
    if (!IsRenderHandlerSubscriptionEnabled(state_, kRenderHandlerStartDragging)) {
      return false;
    }
    const auto drag_handle = drag_data ? RegisterDragData(drag_data->Clone()) : 0;
    const auto response = EmitNotificationEventV4(
        state_, L"cef_render_handler_t", L"start_dragging",
        L"OSR开始拖放",
        L"{\"browserId\":"
            + std::to_wstring(browser ? browser->GetIdentifier() : 0)
            + L",\"allowedOperations\":"
            + std::to_wstring(static_cast<uint32_t>(allowed_ops))
            + L",\"x\":" + std::to_wstring(x)
            + L",\"y\":" + std::to_wstring(y) + L"}",
        drag_handle, true);
    if (drag_handle) LB_CEF3_HandleRelease(drag_handle);
    const bool fallback = response.action == 1 || response.action == 3;
    return EventResponseBool(
        ParseEventResponse(response.response_json), "handled", fallback);
  }

