  bool GetAudioParameters(CefRefPtr<CefBrowser> browser,
                          CefAudioParameters& params) override {
    const auto response = EmitEvent(state_, 104, L"音频参数请求", L"{\"size\":"
        + std::to_wstring(params.size) + L",\"channelLayout\":"
        + std::to_wstring(static_cast<int>(params.channel_layout)) + L",\"sampleRate\":"
        + std::to_wstring(params.sample_rate) + L",\"framesPerBuffer\":"
        + std::to_wstring(params.frames_per_buffer) + L",\"browserId\":"
        + std::to_wstring(browser ? browser->GetIdentifier() : 0) + L"}", true);
    if (response.action == 2) return false;
    if (response.response_json && (response.action == 1 || response.action == 3)) {
      auto parsed = ParseEventResponse(response.response_json);
      if (parsed) {
        if (parsed->HasKey("channelLayout") && parsed->GetType("channelLayout") == VTYPE_INT) {
          params.channel_layout = static_cast<cef_channel_layout_t>(parsed->GetInt("channelLayout"));
        }
        if (parsed->HasKey("sampleRate") && parsed->GetType("sampleRate") == VTYPE_INT) {
          params.sample_rate = parsed->GetInt("sampleRate");
        }
        if (parsed->HasKey("framesPerBuffer") && parsed->GetType("framesPerBuffer") == VTYPE_INT) {
          params.frames_per_buffer = parsed->GetInt("framesPerBuffer");
        }
      }
    }
    return true;
  }

  void OnAudioStreamStarted(CefRefPtr<CefBrowser> browser,
                            const CefAudioParameters& params, int channels) override {
    audio_channels_ = std::max(channels, 1);
    EmitEvent(state_, 105, L"音频流开始", L"{\"browserId\":"
        + std::to_wstring(browser ? browser->GetIdentifier() : 0) + L",\"channelLayout\":"
        + std::to_wstring(static_cast<int>(params.channel_layout)) + L",\"sampleRate\":"
        + std::to_wstring(params.sample_rate) + L",\"framesPerBuffer\":"
        + std::to_wstring(params.frames_per_buffer) + L",\"channels\":"
        + std::to_wstring(audio_channels_) + L"}");
  }

  void OnAudioStreamPacket(CefRefPtr<CefBrowser> browser, const float** data,
                           int frames, int64_t pts) override {
    const int channels = std::max(audio_channels_, 1);
    const size_t safe_frames = frames > 0 ? static_cast<size_t>(frames) : 0;
    const size_t sample_count = safe_frames > SIZE_MAX / static_cast<size_t>(channels)
        ? 0 : safe_frames * static_cast<size_t>(channels);
    std::vector<float> interleaved(sample_count, 0.0f);
    if (data && sample_count > 0) {
      for (int channel = 0; channel < channels; ++channel) {
        if (!data[channel]) continue;
        for (size_t frame = 0; frame < safe_frames; ++frame) {
          interleaved[frame * static_cast<size_t>(channels) + static_cast<size_t>(channel)] = data[channel][frame];
        }
      }
    }
    const auto buffer = sample_count > 0
        ? LB_CEF3_BufferCreate(interleaved.data(), interleaved.size() * sizeof(float)) : 0;
    bool delivered = false;
    EmitEvent(state_, 106, L"音频数据包", L"{\"browserId\":"
        + std::to_wstring(browser ? browser->GetIdentifier() : 0) + L",\"frames\":"
        + std::to_wstring(frames) + L",\"channels\":" + std::to_wstring(channels)
        + L",\"pts\":" + std::to_wstring(pts) + L",\"buffer\":"
        + std::to_wstring(buffer) + L"}", false, &delivered);
    if (buffer != 0 && !delivered) LB_CEF3_BufferRelease(buffer);
  }

