  bool GetAuthCredentials(CefRefPtr<CefBrowser> browser, const CefString& origin_url,
                          bool is_proxy, const CefString& host, int port,
                          const CefString& realm, const CefString& scheme,
                          CefRefPtr<CefAuthCallback> callback) override {
    const auto fields = L"{\"browserId\":"
        + std::to_wstring(browser ? browser->GetIdentifier() : 0) + L",\"originUrl\":\""
        + JsonEscape(origin_url.ToWString()) + L"\",\"isProxy\":"
        + std::wstring(is_proxy ? L"true" : L"false") + L",\"host\":\""
        + JsonEscape(host.ToWString()) + L"\",\"port\":" + std::to_wstring(port)
        + L",\"realm\":\"" + JsonEscape(realm.ToWString()) + L"\",\"scheme\":\""
        + JsonEscape(scheme.ToWString()) + L"\"}";
    auto complete = [callback](int action, const std::wstring& response_json) {
      if (!callback) return;
      if (action != 1 && action != 3) { callback->Cancel(); return; }
      auto parsed = ParseEventResponse(response_json.c_str());
      const auto username = parsed && parsed->HasKey("username")
          && parsed->GetType("username") == VTYPE_STRING ? parsed->GetString("username") : CefString();
      const auto password = parsed && parsed->HasKey("password")
          && parsed->GetType("password") == VTYPE_STRING ? parsed->GetString("password") : CefString();
      callback->Continue(username, password);
    };
    auto async = EmitAsyncEvent(state_, 120, L"cef_request_handler_t",
                                L"get_auth_credentials", L"身份验证请求",
                                fields, 5000, 2, std::move(complete));
    return async.delivered;
  }

  bool OnCertificateError(CefRefPtr<CefBrowser> browser, cef_errorcode_t cert_error,
                          const CefString& request_url, CefRefPtr<CefSSLInfo> ssl_info,
                          CefRefPtr<CefCallback> callback) override {
    const auto fields = L"{\"browserId\":"
        + std::to_wstring(browser ? browser->GetIdentifier() : 0) + L",\"certError\":"
        + std::to_wstring(static_cast<int>(cert_error)) + L",\"requestUrl\":\""
        + JsonEscape(request_url.ToWString()) + L"\",\"hasSslInfo\":"
        + std::wstring(ssl_info ? L"true" : L"false") + L"}";
    auto complete = [callback](int action, const std::wstring&) {
      if (!callback) return;
      if (action == 1 || action == 3) callback->Continue(); else callback->Cancel();
    };
    auto async = EmitAsyncEvent(state_, 121, L"cef_request_handler_t",
                                L"on_certificate_error", L"证书错误",
                                fields, 5000, 2, std::move(complete));
    return async.delivered;
  }

  bool OnRenderProcessUnresponsive(CefRefPtr<CefBrowser> browser,
                                   CefRefPtr<CefUnresponsiveProcessCallback> callback) override {
    const auto fields = L"{\"browserId\":"
        + std::to_wstring(browser ? browser->GetIdentifier() : 0) + L"}";
    auto complete = [callback](int action, const std::wstring&) {
      if (!callback) return;
      if (action == 2) callback->Terminate(); else callback->Wait();
    };
    auto async = EmitAsyncEvent(state_, 122, L"cef_request_handler_t",
                                L"on_render_process_unresponsive", L"渲染进程无响应",
                                fields, 2000, 1, std::move(complete));
    return async.delivered;
  }

