  void OnBeforeClose(CefRefPtr<CefBrowser> browser) override {
    EmitEvent(state_, 2, L"浏览器即将关闭", L"{}");
    NotifyDevToolsAgentDetached(state_, browser ? browser->GetIdentifier() : 0);
    CefRefPtr<CefRegistration> devtools_observer_registration;
    bool preserve_detached_subscription = false;
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      preserve_detached_subscription =
          (state_->devtools_observer_subscriptions & kDevToolsObserverAgentDetached) != 0;
      devtools_observer_registration = std::move(state_->devtools_observer_registration);
      state_->devtools_observer_subscriptions = preserve_detached_subscription
          ? kDevToolsObserverAgentDetached : 0;
      state_->download_handler_subscriptions = 0;
      state_->request_handler_subscriptions = 0;
      state_->resource_request_handler_subscriptions = 0;
      state_->render_process_handler_subscriptions = 0;
      state_->response_filter.reset();
      state_->resource_handler.reset();
      state_->last_download_callback.reset();
      state_->browser = nullptr;
      state_->client = nullptr;
      state_->request_context = nullptr;
      state_->closed = true;
    }
    FailDomRequestsForBrowser(
        state_, L"浏览器关闭，未完成的DOM访问或写入任务已失效");
    FailV8RequestsForBrowser(
        state_, L"浏览器关闭，未完成的renderer V8任务已失效");
    // OnBeforeClose is on CEF UI, so releasing the registration here keeps the
    // observer lifecycle on the same thread as AddDevToolsMessageObserver.
    devtools_observer_registration = nullptr;
    if (preserve_detached_subscription) {
      std::lock_guard<std::mutex> lock(state_->mutex);
      state_->devtools_observer_subscriptions = 0;
    }
    bool final_public_browser = false;
    {
      std::lock_guard<std::mutex> lock(g_mutex);
      g_browser_states.erase(state_->handle);
      for (auto iterator = g_browser_states.begin(); iterator != g_browser_states.end();) {
        if (iterator->second.expired()) iterator = g_browser_states.erase(iterator);
        else ++iterator;
      }
      final_public_browser = g_browser_states.empty();
    }
    ReleaseJsHookHandlesForBrowser(state_);
    ReleaseV8HandlesForBrowser(state_);
    ReleaseFrameHandlesForBrowser(state_);
    if (final_public_browser) {
      ReleaseCefObjectsForFinalBrowserClose();
    }
    state_->changed.notify_all();
    // OnBeforeClose is not the final browser-process cleanup point. Queue a
    // UI barrier while the CEF task runner is still guaranteed to accept work
    // and make Shutdown wait for it before calling CefShutdown.
    const auto state = state_;
    if (!CefPostTask(TID_UI, new BridgeFunctionTask([state]() {
          {
            std::lock_guard<std::mutex> lock(state->mutex);
            state->close_cleanup_complete = true;
          }
          std::fprintf(stderr, "CEF3 browser close barrier completed\\n");
          state->changed.notify_all();
        }))) {
      {
        std::lock_guard<std::mutex> lock(state_->mutex);
        state_->close_cleanup_complete = true;
      }
      state_->changed.notify_all();
    }
  }
