  bool OnJSDialog(CefRefPtr<CefBrowser>, const CefString& origin_url,
                  JSDialogType dialog_type, const CefString& message_text,
                  const CefString& default_prompt_text,
                  CefRefPtr<CefJSDialogCallback> callback,
                  bool& suppress_message) override {
    auto response = EmitEvent(state_, 30, L"脚本对话框请求", L"{\"originUrl\":\""
      + JsonEscape(origin_url.ToWString()) + L"\",\"dialogType\":" + std::to_wstring(dialog_type)
      + L",\"messageText\":\"" + JsonEscape(message_text.ToWString())
      + L"\",\"defaultPromptText\":\"" + JsonEscape(default_prompt_text.ToWString()) + L"\"}", true);
    if (response.action == 2) {
      suppress_message = true;
      return false;
    }
    if ((response.action == 1 || response.action == 3) && callback) {
      callback->Continue(true, response.response_json ? response.response_json : default_prompt_text);
      return true;
    }
    return false;
  }
