  bool RunContextMenu(CefRefPtr<CefBrowser>, CefRefPtr<CefFrame> frame,
                      CefRefPtr<CefContextMenuParams> params,
                      CefRefPtr<CefMenuModel> model,
                      CefRefPtr<CefRunContextMenuCallback> callback) override {
    auto response = EmitEvent(state_, 35, L"运行上下文菜单",
                              ContextMenuParamsJson(frame, params, model), true);
    if (response.action == 0 || !callback) return false;
    if (response.action == 2) {
      callback->Cancel();
    } else {
      auto parsed = ParseEventResponse(response.response_json);
      callback->Continue(EventResponseInt(parsed, "commandId", -1),
                         static_cast<cef_event_flags_t>(EventResponseInt(parsed, "eventFlags", 0)));
    }
    return true;
  }
