    if (!fields.empty() && fields.back() == L'}') fields.pop_back();
    fields += L",\"commandId\":" + std::to_wstring(command_id)
        + L",\"eventFlags\":" + std::to_wstring(event_flags) + L"}";
    return EmitEvent(state_, 36, L"上下文菜单命令", fields, true).action == 3;
