void CompleteMediaCollectionTask(
    const std::shared_ptr<TaskState>& task,
    const std::shared_ptr<MediaCollectionState>& collection) {
  if (!task || !collection) return;
  {
    std::lock_guard<std::mutex> lock(task->mutex);
    if (task->status.load() == LB_CEF3_TASK_CANCELLED) return;
    task->media_collection_result = collection;
    task->media_collection_result_ready = true;
  }
  const size_t count = collection->kind == MediaCollectionKind::kSinks
      ? collection->sinks.size() : collection->routes.size();
  CompleteTask(
      task, true,
      L"{\"kind\":\""
          + std::wstring(collection->kind == MediaCollectionKind::kSinks
                ? L"sinks" : L"routes")
          + L"\",\"count\":" + std::to_wstring(count) + L"}");
}

void DeliverMediaCollection(
    const std::weak_ptr<MediaObserverState>& weak_state,
    std::shared_ptr<MediaCollectionState> collection) {
  const auto state = weak_state.lock();
  if (!state || !collection) return;
  std::shared_ptr<TaskState> waiter;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (!state->active) return;
    auto& waiters = collection->kind == MediaCollectionKind::kSinks
        ? state->sink_waiters : state->route_waiters;
    while (!waiters.empty()) {
      waiter = std::move(waiters.front());
      waiters.pop_front();
      if (waiter && waiter->status.load() != LB_CEF3_TASK_CANCELLED) break;
      waiter.reset();
    }
    if (!waiter) {
      auto& queue = collection->kind == MediaCollectionKind::kSinks
          ? state->queued_sinks : state->queued_routes;
      constexpr size_t kMaximumQueuedMediaCollections = 16;
      if (queue.size() == kMaximumQueuedMediaCollections) queue.pop_front();
      queue.push_back(std::move(collection));
      return;
    }
  }
  CompleteMediaCollectionTask(waiter, collection);
}

enum class MediaObserverEventKind {
  kRouteState,
  kRouteMessage
};

void CompleteMediaObserverEventTask(
    const std::shared_ptr<TaskState>& task, MediaObserverEvent event) {
  if (!task) return;
  task->cef_backed.store(true, std::memory_order_release);
  {
    std::lock_guard<std::mutex> lock(task->mutex);
    if (task->status.load() == LB_CEF3_TASK_CANCELLED) return;
    task->media_route_result = std::move(event.route);
    task->media_route_result_ready = true;
    task->media_buffer_result = std::move(event.buffer);
    task->media_buffer_result_ready = task->media_buffer_result != nullptr;
  }
  CompleteTask(task, event.success, std::move(event.value));
}

void DeliverMediaObserverEvent(
    const std::weak_ptr<MediaObserverState>& weak_state,
    MediaObserverEventKind kind, MediaObserverEvent event) {
  const auto state = weak_state.lock();
  if (!state) return;
  std::shared_ptr<TaskState> waiter;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (!state->active) return;
    auto& waiters = kind == MediaObserverEventKind::kRouteState
        ? state->route_state_waiters : state->route_message_waiters;
    while (!waiters.empty()) {
      waiter = std::move(waiters.front());
      waiters.pop_front();
      if (waiter && waiter->status.load() != LB_CEF3_TASK_CANCELLED) break;
      waiter.reset();
    }
    if (!waiter) {
      auto& queue = kind == MediaObserverEventKind::kRouteState
          ? state->queued_route_states : state->queued_route_messages;
      constexpr size_t kMaximumQueuedMediaObserverEvents = 64;
      if (queue.size() == kMaximumQueuedMediaObserverEvents) queue.pop_front();
      queue.push_back(std::move(event));
      return;
    }
  }
  CompleteMediaObserverEventTask(waiter, std::move(event));
}

class BridgeMediaObserver final : public CefMediaObserver {
 public:
  explicit BridgeMediaObserver(const std::shared_ptr<MediaObserverState>& state)
      : state_(state) {}

  void OnSinks(
      const std::vector<CefRefPtr<CefMediaSink>>& sinks) override {
    auto collection = std::make_shared<MediaCollectionState>(
        MediaCollectionKind::kSinks);
    collection->sinks = sinks;
    DeliverMediaCollection(state_, std::move(collection));
  }

  void OnRoutes(
      const std::vector<CefRefPtr<CefMediaRoute>>& routes) override {
    auto collection = std::make_shared<MediaCollectionState>(
        MediaCollectionKind::kRoutes);
    collection->routes = routes;
    DeliverMediaCollection(state_, std::move(collection));
  }

  void OnRouteStateChanged(
      CefRefPtr<CefMediaRoute> route, ConnectionState connection_state) override {
    MediaObserverEvent event;
    event.value = L"{\"kind\":\"routeStateChanged\",\"state\":"
        + std::to_wstring(static_cast<int32_t>(connection_state)) + L"}";
    if (route) {
      event.route = std::make_shared<MediaRouteState>();
      event.route->route = std::move(route);
    }
    DeliverMediaObserverEvent(
        state_, MediaObserverEventKind::kRouteState, std::move(event));
  }

  void OnRouteMessageReceived(
      CefRefPtr<CefMediaRoute> route, const void* message,
      size_t message_size) override {
    MediaObserverEvent event;
    if (route) {
      event.route = std::make_shared<MediaRouteState>();
      event.route->route = std::move(route);
    }
    if (message_size > kMaximumManagedStreamBytes
        || (message_size > 0 && !message)) {
      event.success = false;
      event.value = L"Media route message exceeds the managed buffer limit";
    } else {
      event.buffer = std::make_shared<BufferState>();
      if (message_size > 0) {
        const auto* bytes = static_cast<const unsigned char*>(message);
        event.buffer->bytes.assign(bytes, bytes + message_size);
      }
      event.value = L"{\"kind\":\"routeMessageReceived\",\"size\":"
          + std::to_wstring(message_size) + L"}";
    }
    DeliverMediaObserverEvent(
        state_, MediaObserverEventKind::kRouteMessage, std::move(event));
  }

 private:
  std::weak_ptr<MediaObserverState> state_;
  IMPLEMENT_REFCOUNTING(BridgeMediaObserver);
};

