void DeliverObserverEvent(
    const std::weak_ptr<ObserverRegistrationState>& weak_state,
    std::wstring event_json) {
  const auto state = weak_state.lock();
  if (!state) return;
  std::shared_ptr<TaskState> waiter;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (!state->active) return;
    while (!state->waiters.empty()) {
      waiter = std::move(state->waiters.front());
      state->waiters.pop_front();
      if (waiter && waiter->status.load() != LB_CEF3_TASK_CANCELLED) break;
      waiter.reset();
    }
    if (!waiter) {
      constexpr size_t kMaximumQueuedObserverEvents = 64;
      if (state->queued_events.size() == kMaximumQueuedObserverEvents)
        state->queued_events.pop_front();
      state->queued_events.push_back(std::move(event_json));
      return;
    }
  }
  CompleteTask(waiter, true, std::move(event_json));
}

