void CompleteImageTask(
    const std::shared_ptr<TaskState>& state, const CefString& image_url,
    int http_status_code, CefRefPtr<CefImage> image) {
  if (!state) return;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (state->status.load() == LB_CEF3_TASK_CANCELLED) return;
    state->image_result = std::move(image);
    state->image_result_ready = true;
    state->result = L"{\"imageUrl\":\"" + JsonEscape(image_url.ToWString())
        + L"\",\"httpStatusCode\":" + std::to_wstring(http_status_code)
        + L",\"hasImage\":" + (state->image_result ? L"true" : L"false") + L"}";
    state->status.store(LB_CEF3_TASK_SUCCEEDED);
  }
  state->changed.notify_all();
}

