int CompleteStringVisitorTask(LB_CEF3_TASK_HANDLE task, const wchar_t* value) {
  if (!value) return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"字符串访问结果不能为空指针");
  int status = LB_CEF3_OK;
  auto state = GetTask(task, status);
  if (!state) return status;
  return CompleteTask(state, true, value), LB_CEF3_OK;
}

int ExecuteTaskState(const std::shared_ptr<TaskState>& state,
                     std::wstring result = L"{\"executed\":true}") {
  if (!state) return Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"任务句柄无效");
  int expected = LB_CEF3_TASK_PENDING;
  if (!state->status.compare_exchange_strong(expected, LB_CEF3_TASK_RUNNING)
      && expected != LB_CEF3_TASK_RUNNING) {
    if (expected == LB_CEF3_TASK_CANCELLED) {
      return Fail(LB_CEF3_ERROR_CANCELLED, L"任务已取消");
    }
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"任务已经完成");
  }
  CompleteTask(state, true, std::move(result));
  return LB_CEF3_OK;
}

bool PostScheduledTask(CefThreadId thread_id, const std::shared_ptr<TaskState>& task) {
  if (!g_cef_initialized.load()) return false;
  auto callback = [task]() {
    ExecuteTaskState(task, L"{\"scheduled\":true}");
  };
  if (thread_id == TID_UI) return PostToCefUi(std::move(callback));
  return CefPostTask(thread_id, new BridgeFunctionTask(std::move(callback)));
}

void StartTaskDelayScheduler() {
  if (g_delayed_task_scheduler) return;
  g_delayed_task_scheduler = std::make_unique<std::jthread>([](std::stop_token stop_token) {
    while (!stop_token.stop_requested()) {
      std::vector<DelayedTaskDispatch> due;
      {
        std::unique_lock<std::mutex> lock(g_delayed_task_mutex);
        if (g_delayed_tasks.empty()) {
          g_delayed_task_changed.wait(lock, [&] {
            return stop_token.stop_requested() || !g_delayed_tasks.empty();
          });
        } else {
          const auto earliest = std::min_element(
              g_delayed_tasks.begin(), g_delayed_tasks.end(),
              [](const DelayedTaskDispatch& left, const DelayedTaskDispatch& right) {
                return left.deadline < right.deadline;
              });
          g_delayed_task_changed.wait_until(lock, earliest->deadline);
        }
        if (stop_token.stop_requested()) break;
        const auto now = std::chrono::steady_clock::now();
        auto split = std::stable_partition(
            g_delayed_tasks.begin(), g_delayed_tasks.end(),
            [now](const DelayedTaskDispatch& dispatch) { return dispatch.deadline > now; });
        due.assign(std::make_move_iterator(split), std::make_move_iterator(g_delayed_tasks.end()));
        g_delayed_tasks.erase(split, g_delayed_tasks.end());
      }
      for (const auto& dispatch : due) {
        if (!dispatch.task || dispatch.task->status.load() == LB_CEF3_TASK_CANCELLED) continue;
        if (!PostScheduledTask(dispatch.thread_id, dispatch.task)) {
          CompleteTask(dispatch.task, false, L"CEF线程拒绝延迟任务");
        }
      }
    }
  });
}

void StopTaskDelayScheduler() {
  if (g_delayed_task_scheduler) {
    g_delayed_task_scheduler->request_stop();
    g_delayed_task_changed.notify_all();
    g_delayed_task_scheduler.reset();
  }
  std::vector<std::shared_ptr<TaskState>> cancelled;
  {
    std::lock_guard<std::mutex> lock(g_delayed_task_mutex);
    for (const auto& dispatch : g_delayed_tasks) {
      if (dispatch.task) cancelled.push_back(dispatch.task);
    }
    g_delayed_tasks.clear();
  }
  for (const auto& task : cancelled) {
    int expected = LB_CEF3_TASK_RUNNING;
    if (task->status.compare_exchange_strong(expected, LB_CEF3_TASK_CANCELLED)) {
      task->changed.notify_all();
    }
  }
}

bool ScheduleDelayedTask(
    CefThreadId thread_id, const std::shared_ptr<TaskState>& task, int64_t delay_ms) {
  if (!task || delay_ms < 0 || !g_cef_initialized.load()) return false;
  {
    std::lock_guard<std::mutex> lock(g_delayed_task_mutex);
    g_delayed_tasks.push_back({thread_id,
        std::chrono::steady_clock::now() + std::chrono::milliseconds(delay_ms), task});
  }
  g_delayed_task_changed.notify_one();
  return true;
}

