double BaseTimeSeconds(const cef_basetime_t value) {
  CefTime converted;
  return cef_time_from_basetime(value, &converted) ? converted.GetDoubleT() : 0.0;
}

class BridgeCookieVisitor final : public CefCookieVisitor {
 public:
  explicit BridgeCookieVisitor(std::shared_ptr<TaskState> state) : state_(std::move(state)) {}
  ~BridgeCookieVisitor() override { if (started_.load()) Finish(); }

  void MarkStarted() { started_.store(true); }

  bool Visit(const CefCookie& cookie, int count, int total, bool& delete_cookie) override {
    started_.store(true);
    delete_cookie = false;
    const auto name = CefString(&cookie.name).ToWString();
    const auto value = CefString(&cookie.value).ToWString();
    const auto domain = CefString(&cookie.domain).ToWString();
    const auto path = CefString(&cookie.path).ToWString();
    std::wostringstream item;
    item << L"{\"name\":\"" << JsonEscape(name)
         << L"\",\"value\":\"" << JsonEscape(value)
         << L"\",\"domain\":\"" << JsonEscape(domain)
         << L"\",\"path\":\"" << JsonEscape(path)
         << L"\",\"secure\":" << (cookie.secure ? L"true" : L"false")
         << L",\"httpOnly\":" << (cookie.httponly ? L"true" : L"false")
         << L",\"hasExpires\":" << (cookie.has_expires ? L"true" : L"false")
         << L",\"expires\":" << std::fixed << std::setprecision(0)
         << (cookie.has_expires ? BaseTimeSeconds(cookie.expires) : 0.0)
         << L",\"sameSite\":" << static_cast<int>(cookie.same_site)
         << L",\"priority\":" << static_cast<int>(cookie.priority) << L"}";
    items_.push_back(item.str());
    if (count + 1 >= total) Finish();
    return true;
  }

 private:
  void Finish() {
    if (finished_.exchange(true)) return;
    std::wstring json = L"[";
    for (size_t index = 0; index < items_.size(); ++index) {
      if (index > 0) json += L",";
      json += items_[index];
    }
    json += L"]";
    CompleteTask(state_, true, std::move(json));
  }

  std::shared_ptr<TaskState> state_;
  std::vector<std::wstring> items_;
  std::atomic<bool> started_{false};
  std::atomic<bool> finished_{false};
  IMPLEMENT_REFCOUNTING(BridgeCookieVisitor);
};

class BridgeNavigationEntryVisitor final : public CefNavigationEntryVisitor {
 public:
  explicit BridgeNavigationEntryVisitor(std::shared_ptr<TaskState> state) : state_(std::move(state)) {}
  ~BridgeNavigationEntryVisitor() override { Finish(); }

  bool Visit(CefRefPtr<CefNavigationEntry> entry, bool current, int index, int total) override {
    if (entry) {
      const auto completion = entry->GetCompletionTime();
      const double completion_seconds = completion.val == 0
        ? 0.0 : static_cast<double>(completion.val) / 1000000.0 - 11644473600.0;
      std::wostringstream item;
      item << L"{\"current\":" << (current ? L"true" : L"false")
           << L",\"index\":" << index << L",\"total\":" << total
           << L",\"valid\":" << (entry->IsValid() ? L"true" : L"false")
           << L",\"url\":\"" << JsonEscape(entry->GetURL().ToWString())
           << L"\",\"displayUrl\":\"" << JsonEscape(entry->GetDisplayURL().ToWString())
           << L"\",\"originalUrl\":\"" << JsonEscape(entry->GetOriginalURL().ToWString())
           << L"\",\"title\":\"" << JsonEscape(entry->GetTitle().ToWString())
           << L"\",\"transitionType\":" << static_cast<int>(entry->GetTransitionType())
           << L",\"hasPostData\":" << (entry->HasPostData() ? L"true" : L"false")
           << L",\"completionTime\":" << std::fixed << std::setprecision(6) << completion_seconds
           << L",\"httpStatusCode\":" << entry->GetHttpStatusCode() << L"}";
      items_.push_back(item.str());
    }
    if (index + 1 >= total) Finish();
    return true;
  }

 private:
  void Finish() {
    if (finished_.exchange(true)) return;
    std::wstring json = L"[";
    for (size_t index = 0; index < items_.size(); ++index) {
      if (index) json += L",";
      json += items_[index];
    }
    json += L"]";
    CompleteTask(state_, true, std::move(json));
  }
  std::shared_ptr<TaskState> state_;
  std::vector<std::wstring> items_;
  std::atomic<bool> finished_{false};
  IMPLEMENT_REFCOUNTING(BridgeNavigationEntryVisitor);
};

std::wstring Utf8ToWide(const void* data, size_t size) {
  if (!data || size == 0 || size > static_cast<size_t>(INT_MAX)) return L"";
  int count = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, static_cast<const char*>(data),
                                  static_cast<int>(size), nullptr, 0);
  if (count <= 0) return L"";
  std::wstring result(static_cast<size_t>(count), L'\0');
  MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, static_cast<const char*>(data),
                      static_cast<int>(size), result.data(), count);
  return result;
}

std::string WideToUtf8(const wchar_t* value) {
  if (!value || !*value) return {};
  const int source_length = static_cast<int>(wcslen(value));
  const int length = WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, value, source_length,
                                         nullptr, 0, nullptr, nullptr);
  if (length <= 0) return {};
  std::string result(static_cast<size_t>(length), '\0');
  if (WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, value, source_length,
                          result.data(), length, nullptr, nullptr) != length) {
    return {};
  }
  return result;
}

constexpr size_t kMaximumDevToolsEventBytes = 1024 * 1024;

bool IsDevToolsObserverSubscriptionEnabled(const std::shared_ptr<BrowserState>& state,
                                           uint32_t subscription) {
  if (!state) return false;
  std::lock_guard<std::mutex> lock(state->mutex);
  return (state->devtools_observer_subscriptions & subscription) != 0;
}

std::wstring DevToolsPayloadJson(const wchar_t* property, const void* data, size_t data_size) {
  const size_t copied_size = std::min(data_size, kMaximumDevToolsEventBytes);
  const std::wstring value = copied_size == 0 ? L"" : Utf8ToWide(data, copied_size);
  const bool utf8_valid = copied_size == 0 || !value.empty();
  std::wostringstream json;
  json << L"\"" << property << L"\":\"" << JsonEscape(value)
       << L"\",\"byteCount\":" << data_size
       << L",\"truncated\":" << (copied_size != data_size ? L"true" : L"false")
       << L",\"utf8Valid\":" << (utf8_valid ? L"true" : L"false");
  return json.str();
}

void EmitDevToolsObserverNotification(const std::shared_ptr<BrowserState>& state,
                                      uint32_t subscription, int event_code,
                                      const wchar_t* official_name,
                                      const wchar_t* event_name,
                                      std::wstring fields_json) {
  if (!IsDevToolsObserverSubscriptionEnabled(state, subscription)) return;
  EmitEvent(state, event_code, event_name, fields_json);
  EmitNotificationEventV4(state, L"cef_dev_tools_message_observer_t", official_name,
                          event_name, fields_json);
}

void NotifyDevToolsAgentDetached(const std::shared_ptr<BrowserState>& state,
                                 int browser_id) {
  if (!state || !IsDevToolsObserverSubscriptionEnabled(
      state, kDevToolsObserverAgentDetached)) return;
  if (state->devtools_agent_detached_notified.exchange(true)) return;
  state->devtools_agent_attached.store(false);
  EmitDevToolsObserverNotification(
      state, kDevToolsObserverAgentDetached, 129, L"on_dev_tools_agent_detached",
      L"开发工具代理已分离", L"{\"browserId\":" + std::to_wstring(browser_id) + L"}");
}

class BridgeDevToolsObserver final : public CefDevToolsMessageObserver {
 public:
  explicit BridgeDevToolsObserver(std::weak_ptr<BrowserState> state) : state_(std::move(state)) {}

  bool OnDevToolsMessage(CefRefPtr<CefBrowser> browser, const void* message,
                         size_t message_size) override {
    auto state = state_.lock();
    if (!state) return false;
    const auto browser_id = browser ? browser->GetIdentifier() : 0;
    EmitDevToolsObserverNotification(
        state, kDevToolsObserverMessage, 131, L"on_dev_tools_message", L"开发工具协议消息",
        L"{\"browserId\":" + std::to_wstring(browser_id) + L"," +
            DevToolsPayloadJson(L"message", message, message_size) + L"}");
    // This observer only mirrors protocol traffic. Returning false keeps CEF's
    // method-result and event callbacks available to other bridge observers.
    return false;
  }

  void OnDevToolsEvent(CefRefPtr<CefBrowser> browser, const CefString& method,
                       const void* params, size_t params_size) override {
    auto state = state_.lock();
    if (!state) return;
    const auto browser_id = browser ? browser->GetIdentifier() : 0;
    EmitDevToolsObserverNotification(
        state, kDevToolsObserverEvent, 130, L"on_dev_tools_event", L"开发工具协议事件",
        L"{\"browserId\":" + std::to_wstring(browser_id) + L",\"method\":\"" +
            JsonEscape(method.ToWString()) + L"\"," +
            DevToolsPayloadJson(L"paramsJson", params, params_size) + L"}");
  }

  void OnDevToolsAgentAttached(CefRefPtr<CefBrowser> browser) override {
    auto state = state_.lock();
    if (!state) return;
    state->devtools_agent_attached.store(true);
    state->devtools_agent_detached_notified.store(false);
    EmitDevToolsObserverNotification(
        state, kDevToolsObserverAgentAttached, 128, L"on_dev_tools_agent_attached",
        L"开发工具代理已附加", L"{\"browserId\":" +
            std::to_wstring(browser ? browser->GetIdentifier() : 0) + L"}");
  }

  void OnDevToolsAgentDetached(CefRefPtr<CefBrowser> browser) override {
    auto state = state_.lock();
    if (!state) return;
    NotifyDevToolsAgentDetached(state, browser ? browser->GetIdentifier() : 0);
  }

 private:
  std::weak_ptr<BrowserState> state_;
  IMPLEMENT_REFCOUNTING(BridgeDevToolsObserver);
};

class BridgeEvalObserver final : public CefDevToolsMessageObserver {
 public:
  explicit BridgeEvalObserver(std::shared_ptr<TaskState> state) : state_(std::move(state)) {}
  void OnDevToolsMethodResult(CefRefPtr<CefBrowser>, int message_id, bool success,
                              const void* result, size_t result_size) override {
    if (state_->message_id != 0 && state_->message_id != message_id) return;
    CompleteTask(state_, success, Utf8ToWide(result, result_size));
  }
 private:
  std::shared_ptr<TaskState> state_;
  IMPLEMENT_REFCOUNTING(BridgeEvalObserver);
};

std::wstring NormalizeProfileKey(const wchar_t* value, uint64_t user_token) {
  std::wstring key = value && *value ? value : std::to_wstring(user_token);
  const size_t digest = std::hash<std::wstring>{}(key);
  return L"profile-" + std::to_wstring(user_token) + L"-" + std::to_wstring(static_cast<unsigned long long>(digest));
}

LB_CEF3_HANDLE CreateBrowserHandle(const LB_CEF3_BROWSER_CONFIG_V3* config, bool chrome_runtime) {
  if (!g_cef_initialized.load()) { Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF3尚未初始化"); return 0; }
  if (!config || config->struct_size < sizeof(LB_CEF3_BROWSER_CONFIG_V3)
      || config->abi_version != LB_CEF3_ABI_VERSION_V3) {
    Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"浏览器配置版本无效"); return 0;
  }
  const bool windowless = (config->flags & LB_CEF3_BROWSER_WINDOWLESS) != 0;
  if (chrome_runtime && windowless) {
    Fail(LB_CEF3_ERROR_NOT_SUPPORTED, L"Chrome Runtime 浏览器不支持无窗口/OSR 创建"); return 0;
  }
  if (!chrome_runtime && config->parent_window == 0) {
    Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"内嵌浏览器必须提供独立宿主HWND"); return 0;
  }
  auto state = std::make_shared<BrowserState>();
  state->user_token = config->user_token;
  state->parent = reinterpret_cast<HWND>(static_cast<uintptr_t>(config->parent_window));
  state->flags = config->flags;
  state->windowless = windowless;
  state->event_callback = config->event_callback;
  state->event_user_data = config->event_user_data;
  state->url = config->initial_url && *config->initial_url ? config->initial_url : L"about:blank";
  state->profile_path = (g_cef_root_cache / NormalizeProfileKey(config->profile_key, config->user_token)).wstring();
  state->proxy_server = config->proxy_server ? config->proxy_server : L"";
  std::error_code directory_error;
  std::filesystem::create_directories(state->profile_path, directory_error);
  if (directory_error) { Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"无法创建CEF3独立缓存目录"); return 0; }

  CefRequestContextSettings context_settings{};
  context_settings.size = sizeof(context_settings);
  CefString(&context_settings.cache_path).FromWString(state->profile_path);
  std::wstring proxy_mode = config->proxy_mode ? config->proxy_mode : L"system";
  if (proxy_mode == L"none") proxy_mode = L"direct";
  if (proxy_mode == L"custom") proxy_mode = L"fixed_servers";
  auto context_handler_state = std::make_shared<RequestContextHandlerState>();
  CefRefPtr<CefRequestContextHandler> context_handler = new BridgeRequestContextHandler(
    proxy_mode, config->proxy_server ? config->proxy_server : L"",
    context_handler_state);
  context_handler_state->handler = context_handler;
  state->request_context_handler = context_handler_state;
  state->request_context = CefRequestContext::CreateContext(context_settings, context_handler);
  if (!state->request_context) { Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"无法创建独立RequestContext"); return 0; }

  HandleEntry entry;
  entry.type = LB_CEF3_HANDLE_BROWSER;
  entry.object = state;
  state->handle = Register(std::move(entry));
  {
    std::lock_guard<std::mutex> lock(g_mutex);
    g_browser_states[state->handle] = state;
  }
  CefRefPtr<BridgeClient> client = new BridgeClient(state);
  state->client = client;
  g_default_browser_state = state;

  const std::wstring initial_url = state->url;
  const bool posted = PostToCefUi([state, client, initial_url, chrome_runtime, windowless]() {
    CefWindowInfo window_info{};
    if (chrome_runtime) {
      window_info.SetAsPopup(nullptr, L"谷歌原生UI浏览器");
      window_info.parent_window = nullptr;
      window_info.ex_style |= WS_EX_APPWINDOW;
      window_info.style &= ~WS_CHILD;
      window_info.runtime_style = CEF_RUNTIME_STYLE_CHROME;
    } else if (windowless) {
      window_info.SetAsWindowless(state->parent);
      window_info.runtime_style = CEF_RUNTIME_STYLE_ALLOY;
    } else {
      RECT bounds{};
      GetClientRect(state->parent, &bounds);
      window_info.SetAsChild(state->parent, CefRect(0, 0, bounds.right - bounds.left, bounds.bottom - bounds.top));
    }
    CefBrowserSettings browser_settings{};
    browser_settings.size = sizeof(browser_settings);
    if ((state->flags & LB_CEF3_BROWSER_JAVASCRIPT) == 0) browser_settings.javascript = STATE_DISABLED;
    if ((state->flags & LB_CEF3_BROWSER_IMAGES) == 0) browser_settings.image_loading = STATE_DISABLED;
    if ((state->flags & LB_CEF3_BROWSER_WEBGL) == 0) browser_settings.webgl = STATE_DISABLED;
    if (!CefBrowserHost::CreateBrowser(window_info, client, initial_url, browser_settings, nullptr, state->request_context)) {
      Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF3创建浏览器请求失败");
    }
  });
  if (!posted) {
    {
      std::lock_guard<std::mutex> lock(g_mutex);
      g_browser_states.erase(state->handle);
    }
    LB_CEF3_HandleRelease(state->handle);
    Fail(LB_CEF3_ERROR_WRONG_THREAD, L"无法投递CEF UI线程");
    return 0;
  }
  return state->handle;
}

std::shared_ptr<BrowserState> GetBrowserState(LB_CEF3_HANDLE handle, int& status) {
  return GetObject<BrowserState>(handle, LB_CEF3_HANDLE_BROWSER, status);
}

CefRefPtr<CefBrowser> SnapshotBrowser(const std::shared_ptr<BrowserState>& state) {
  if (!state) return nullptr;
  std::lock_guard<std::mutex> lock(state->mutex);
  return state->browser;
}

CefRefPtr<CefFrame> SnapshotFrame(
    LB_CEF3_HANDLE handle, int& status,
    std::shared_ptr<FrameState>* frame_state = nullptr) {
  auto state = GetFrameState(handle, status);
  if (!state) return nullptr;
  auto browser_state = state->browser.lock();
  auto browser = SnapshotBrowser(browser_state);
  CefRefPtr<CefFrame> frame;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (browser && !state->identifier.empty()) {
      frame = browser->GetFrameByIdentifier(state->identifier);
    }
    if (!frame && browser && state->main_frame) frame = browser->GetMainFrame();
    if (frame) {
      state->identifier = frame->GetIdentifier().ToWString();
      state->main_frame = frame->IsMain();
      state->frame = frame;
    }
    else frame = state->frame;
  }
  if (!frame) {
    status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"Frame对象已经失效");
    return nullptr;
  }
  if (frame_state) *frame_state = std::move(state);
  status = LB_CEF3_OK;
  return frame;
}

int InvokeFrameAction(
    LB_CEF3_HANDLE handle,
    std::function<void(CefRefPtr<CefFrame>)> action) {
  int status = 0;
  auto frame = SnapshotFrame(handle, status);
  if (!frame) return status;
  if (!frame->IsValid()) {
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"Frame当前未附加到有效文档");
  }
  auto operation_status = std::make_shared<int>(LB_CEF3_ERROR_OPERATION_FAILED);
  if (!RunOnCefUiSync([frame, action = std::move(action), operation_status]() {
        if (!frame->IsValid()) return;
        action(frame);
        *operation_status = LB_CEF3_OK;
      })) {
    return Fail(LB_CEF3_ERROR_TIMEOUT, L"执行CEF UI Frame操作超时");
  }
  return *operation_status == LB_CEF3_OK
      ? LB_CEF3_OK
      : Fail(*operation_status, L"Frame在CEF UI线程执行前已经失效");
}

int PostBrowserAction(LB_CEF3_HANDLE handle, std::function<void(CefRefPtr<CefBrowser>, const std::shared_ptr<BrowserState>&)> action) {
  int status = 0;
  auto state = GetBrowserState(handle, status);
  if (!state) return status;
  auto browser = SnapshotBrowser(state);
  if (!browser) return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF3浏览器尚未创建完成或已经关闭");
  return PostToCefUi([state, browser, action = std::move(action)]() { action(browser, state); })
    ? LB_CEF3_OK : Fail(LB_CEF3_ERROR_WRONG_THREAD, L"无法投递CEF UI线程");
}

int InvokeBrowserHostOnUi(
    LB_CEF3_HANDLE handle,
    const std::function<void(CefRefPtr<CefBrowserHost>)>& action) {
  int status = 0;
  auto state = GetBrowserState(handle, status);
  if (!state) return status;
  auto browser = SnapshotBrowser(state);
  if (!browser)
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF3浏览器尚未创建完成或已经关闭");
  auto operation_status = std::make_shared<int>(LB_CEF3_ERROR_OPERATION_FAILED);
  if (!RunOnCefUiSync([browser, action, operation_status]() {
        auto host = browser->GetHost();
        if (!host) return;
        action(host);
        *operation_status = LB_CEF3_OK;
      })) {
    return Fail(LB_CEF3_ERROR_TIMEOUT, L"CEF3浏览器宿主操作超时");
  }
  if (*operation_status != LB_CEF3_OK)
    return Fail(*operation_status, L"CEF3浏览器宿主不可用");
  return LB_CEF3_OK;
}

int RetainBrowserAlias(LB_CEF3_HANDLE browser, LB_CEF3_HANDLE* result) {
  if (!result) return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"浏览器别名输出参数不能为空");
  *result = 0;
  const int status = LB_CEF3_HandleRetain(browser);
  if (status != LB_CEF3_OK) return status;
  *result = browser;
  return LB_CEF3_OK;
}

int SetDevToolsObserverSubscription(LB_CEF3_HANDLE browser_handle, uint32_t subscription,
                                    int enabled) {
  if (enabled != 0 && enabled != 1) {
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"DevTools订阅只能设置为0或1");
  }
  int status = LB_CEF3_OK;
  auto state = GetBrowserState(browser_handle, status);
  if (!state) return status;
  auto browser = SnapshotBrowser(state);
  if (!browser) return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF3浏览器尚未创建完成或已经关闭");

  auto result = std::make_shared<int>(LB_CEF3_ERROR_OPERATION_FAILED);
  if (!RunOnCefUiSync([state, browser, subscription, enabled, result]() {
        CefRefPtr<CefRegistration> released_registration;
        uint32_t current = 0;
        {
          std::lock_guard<std::mutex> lock(state->mutex);
      if (state->closed || !state->browser || !state->browser->IsSame(browser)) {
            *result = LB_CEF3_ERROR_OPERATION_FAILED;
            return;
          }
          current = state->devtools_observer_subscriptions;
        }
        const uint32_t next = enabled != 0 ? current | subscription : current & ~subscription;
        bool preserve_detached_subscription = false;
        if (next == current) {
          *result = LB_CEF3_OK;
          return;
        }
        if (current == 0 && next != 0) {
          auto host = browser->GetHost();
          if (!host) {
            *result = LB_CEF3_ERROR_OPERATION_FAILED;
            return;
          }
          CefRefPtr<BridgeDevToolsObserver> observer = new BridgeDevToolsObserver(state);
          CefRefPtr<CefRegistration> registration = host->AddDevToolsMessageObserver(observer);
          if (!registration) {
            *result = LB_CEF3_ERROR_OPERATION_FAILED;
            return;
          }
          std::lock_guard<std::mutex> lock(state->mutex);
          state->devtools_observer_registration = std::move(registration);
          state->devtools_observer_subscriptions = next;
        } else if (next == 0) {
          preserve_detached_subscription =
              (current & kDevToolsObserverAgentDetached) != 0;
          {
            std::lock_guard<std::mutex> lock(state->mutex);
            released_registration = std::move(state->devtools_observer_registration);
            state->devtools_observer_subscriptions = preserve_detached_subscription
                ? kDevToolsObserverAgentDetached : 0;
          }
          // CEF may synchronously invoke OnDevToolsAgentDetached while the
          // registration is released, so keep that subscription bit alive
          // until the CefRegistration destructor has run.
          if (preserve_detached_subscription) {
            NotifyDevToolsAgentDetached(state, browser->GetIdentifier());
            released_registration = nullptr;
            std::lock_guard<std::mutex> lock(state->mutex);
            state->devtools_observer_subscriptions = 0;
          }
        } else {
          std::lock_guard<std::mutex> lock(state->mutex);
          state->devtools_observer_subscriptions = next;
        }
        // |released_registration| is destroyed on CEF UI after the state lock
        // is released, which unregisters the observer without a cross-thread
        // CEF release.
        *result = LB_CEF3_OK;
      })) {
    return Fail(LB_CEF3_ERROR_TIMEOUT, L"配置DevTools观察器超时");
  }
  return *result;
}

std::pair<LB_CEF3_TASK_HANDLE, std::shared_ptr<TaskState>> CreateRunningTask() {
  HandleEntry entry;
  entry.type = LB_CEF3_HANDLE_TASK;
  entry.task = std::make_shared<TaskState>();
  entry.task->status.store(LB_CEF3_TASK_RUNNING);
  auto state = entry.task;
  return {Register(std::move(entry)), std::move(state)};
}

void CompleteUrlRequestEventTask(
    const std::shared_ptr<TaskState>& task, UrlRequestEventValue event) {
  if (!task) return;
  task->cef_backed.store(true, std::memory_order_release);
  bool cancelled = false;
  {
    std::lock_guard<std::mutex> lock(task->mutex);
    cancelled = task->status.load() == LB_CEF3_TASK_CANCELLED;
    if (!cancelled) {
      task->url_request_buffer_result = std::move(event.buffer);
      task->url_request_buffer_result_ready =
          task->url_request_buffer_result != nullptr;
      task->url_request_auth_continuation_state =
          std::move(event.continuation_state);
      task->url_request_auth_continuation_handle = event.continuation_handle;
    }
  }
  if (cancelled) {
    if (event.continuation_state) {
      FinishContinuation(
          event.continuation_state,
          event.continuation_state->default_action, L"{}");
    }
    if (event.continuation_handle != 0)
      LB_CEF3_HandleRelease(event.continuation_handle);
    return;
  }
  CompleteTask(task, event.success, std::move(event.value));
}

void DeliverUrlRequestEvent(
    const std::shared_ptr<UrlRequestClientState>& state,
    UrlRequestEventKind kind, UrlRequestEventValue event) {
  if (!state) return;
  const auto index = static_cast<size_t>(kind);
  std::shared_ptr<TaskState> waiter;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (!state->active) return;
    auto& waiters = state->waiters[index];
    while (!waiters.empty()) {
      waiter = std::move(waiters.front());
      waiters.pop_front();
      if (waiter && waiter->status.load() != LB_CEF3_TASK_CANCELLED) break;
      waiter.reset();
    }
    if (!waiter) {
      auto& queue = state->queued_events[index];
      constexpr size_t kMaximumQueuedUrlRequestEvents = 32;
      if (queue.size() == kMaximumQueuedUrlRequestEvents) queue.pop_front();
      queue.push_back(std::move(event));
    }
  }
  if (waiter) CompleteUrlRequestEventTask(waiter, std::move(event));
}

class BridgeUrlRequestClient final : public CefURLRequestClient {
 public:
  explicit BridgeUrlRequestClient(
      std::shared_ptr<UrlRequestClientState> state)
      : state_(std::move(state)) {}

  void OnRequestComplete(CefRefPtr<CefURLRequest> request) override {
    const auto status = request ? request->GetRequestStatus() : UR_UNKNOWN;
    const auto error = request ? request->GetRequestError() : ERR_FAILED;
    const bool cached = request && request->ResponseWasCached();
    DeliverUrlRequestEvent(
        state_, UrlRequestEventKind::kRequestComplete,
        {true,
         L"{\"kind\":\"requestComplete\",\"status\":"
             + std::to_wstring(static_cast<int>(status))
             + L",\"error\":" + std::to_wstring(static_cast<int>(error))
             + L",\"cached\":" + (cached ? L"true" : L"false") + L"}"});
  }

  void OnUploadProgress(
      CefRefPtr<CefURLRequest>, int64_t current, int64_t total) override {
    DeliverUrlRequestEvent(
        state_, UrlRequestEventKind::kUploadProgress,
        {true,
         L"{\"kind\":\"uploadProgress\",\"current\":"
             + std::to_wstring(current) + L",\"total\":"
             + std::to_wstring(total) + L"}"});
  }

  void OnDownloadProgress(
      CefRefPtr<CefURLRequest>, int64_t current, int64_t total) override {
    DeliverUrlRequestEvent(
        state_, UrlRequestEventKind::kDownloadProgress,
        {true,
         L"{\"kind\":\"downloadProgress\",\"current\":"
             + std::to_wstring(current) + L",\"total\":"
             + std::to_wstring(total) + L"}"});
  }

  void OnDownloadData(
      CefRefPtr<CefURLRequest> request,
      const void* data, size_t data_length) override {
    if (data_length > kMaximumManagedStreamBytes
        || (data_length > 0 && !data)) {
      if (request) request->Cancel();
      DeliverUrlRequestEvent(
          state_, UrlRequestEventKind::kDownloadData,
          {false, L"URLRequest下载块超过64 MiB或数据地址无效"});
      return;
    }
    auto buffer = std::make_shared<BufferState>();
    if (data_length > 0) {
      const auto* bytes = static_cast<const unsigned char*>(data);
      buffer->bytes.assign(bytes, bytes + data_length);
    }
    UrlRequestEventValue event;
    event.value = L"{\"kind\":\"downloadData\",\"size\":"
        + std::to_wstring(data_length) + L"}";
    event.buffer = std::move(buffer);
    DeliverUrlRequestEvent(
        state_, UrlRequestEventKind::kDownloadData, std::move(event));
  }

  bool GetAuthCredentials(
      bool is_proxy, const CefString& host, int port,
      const CefString& realm, const CefString& scheme,
      CefRefPtr<CefAuthCallback> callback) override {
    if (!callback) return false;
    std::shared_ptr<TaskState> waiter;
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      if (!state_->active) return false;
      auto& waiters = state_->waiters[
          static_cast<size_t>(UrlRequestEventKind::kAuthCredentials)];
      while (!waiters.empty()) {
        waiter = std::move(waiters.front());
        waiters.pop_front();
        if (waiter && waiter->status.load() != LB_CEF3_TASK_CANCELLED) break;
        waiter.reset();
      }
    }
    // CEF only permits deferred authentication when the callback is retained.
    // Never retain it unless a managed consumer was already waiting.
    if (!waiter) return false;
    auto continuation = CreateContinuation(
        30000, 0,
        [callback](int action, const std::wstring& response_json) {
          if (action != 1) {
            callback->Cancel();
            return;
          }
          auto response = ParseEventResponse(response_json.c_str());
          if (!response
              || !response->HasKey("username")
              || response->GetType("username") != VTYPE_STRING
              || !response->HasKey("password")
              || response->GetType("password") != VTYPE_STRING) {
            callback->Cancel();
            return;
          }
          callback->Continue(
              response->GetString("username"), response->GetString("password"));
        });
    if (continuation.handle == 0) return false;
    UrlRequestEventValue event;
    event.value = L"{\"kind\":\"authCredentials\",\"isProxy\":"
        + std::wstring(is_proxy ? L"true" : L"false")
        + L",\"host\":\"" + JsonEscape(host.ToWString())
        + L"\",\"port\":" + std::to_wstring(port)
        + L",\"realm\":\"" + JsonEscape(realm.ToWString())
        + L"\",\"scheme\":\"" + JsonEscape(scheme.ToWString()) + L"\"}";
    event.continuation_state = std::move(continuation.state);
    event.continuation_handle = continuation.handle;
    CompleteUrlRequestEventTask(waiter, std::move(event));
    return true;
  }

 private:
  std::shared_ptr<UrlRequestClientState> state_;
  IMPLEMENT_REFCOUNTING(BridgeUrlRequestClient);
};

UrlRequestClientState::~UrlRequestClientState() {
  std::array<std::deque<std::shared_ptr<TaskState>>,
             static_cast<size_t>(UrlRequestEventKind::kCount)> pending;
  std::array<std::deque<UrlRequestEventValue>,
             static_cast<size_t>(UrlRequestEventKind::kCount)> queued;
  {
    std::lock_guard<std::mutex> lock(mutex);
    active = false;
    pending.swap(waiters);
    queued.swap(queued_events);
  }
  for (auto& queue : pending) {
    for (const auto& task : queue)
      CompleteTask(task, false, L"URLRequest Client句柄已经失效");
  }
  for (auto& queue : queued) {
    for (auto& event : queue) {
      if (event.continuation_state) {
        FinishContinuation(
            event.continuation_state,
            event.continuation_state->default_action, L"{}");
      }
      if (event.continuation_handle != 0)
        LB_CEF3_HandleRelease(event.continuation_handle);
    }
  }
}

UrlRequestState::~UrlRequestState() {
  CefRefPtr<CefURLRequest> pending;
  {
    std::lock_guard<std::mutex> lock(mutex);
    pending.swap(request);
  }
  if (!pending) return;
  auto* holder = new CefRefPtr<CefURLRequest>(std::move(pending));
  if (!g_cef_initialized.load()) {
    holder->reset();
    delete holder;
    return;
  }
  if (!RunOnCefUiSync([holder]() {
        if (*holder) (*holder)->Cancel();
        holder->reset();
        delete holder;
      })) {
    // Preserve the final CEF reference if its creation thread is unavailable.
  }
}

CefRefPtr<CefCookieManager> GetContextCookieManager(const std::shared_ptr<RequestContextState>& state) {
  return state && state->context ? state->context->GetCookieManager(nullptr) : nullptr;
}

bool FinishContinuation(const std::shared_ptr<ContinuationState>& state, int action,
                        const std::wstring& response_json) {
  std::function<void(int, const std::wstring&)> callback;
  CefRefPtr<CefTaskRunner> task_runner;
  int origin_thread_id = -1;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (state->finished) return false;
    state->finished = true;
    callback = state->complete;
    task_runner = state->task_runner;
    origin_thread_id = state->origin_thread_id;
  }
  if (!callback) return true;
  const auto invoke = [callback = std::move(callback), action, response_json]() {
    callback(action, response_json);
  };
  if (task_runner && !task_runner->BelongsToCurrentThread()) {
    if (task_runner->PostTask(new BridgeFunctionTask(invoke))) return true;
  } else if (!task_runner && origin_thread_id >= 0
      && !CefCurrentlyOn(static_cast<CefThreadId>(origin_thread_id))) {
    if (CefPostTask(static_cast<CefThreadId>(origin_thread_id),
                    new BridgeFunctionTask(invoke))) return true;
  } else {
    invoke();
    return true;
  }
  // A rejected task must stay retryable. Calling the official CEF callback
  // on the timer thread would violate its affinity and can crash during
  // browser teardown.
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    state->finished = false;
  }
  return false;
}

void StartContinuationTimer() {
  if (g_continuation_timer) return;
  g_continuation_timer = std::make_unique<std::jthread>([](std::stop_token stop_token) {
    while (!stop_token.stop_requested()) {
      std::this_thread::sleep_for(std::chrono::milliseconds(25));
      const auto now = std::chrono::steady_clock::now();
      std::vector<std::shared_ptr<ContinuationState>> expired;
      {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (const auto& [handle, entry] : g_handles) {
          (void)handle;
          if (entry.type != LB_CEF3_HANDLE_CONTINUATION || !entry.object) continue;
          auto state = std::static_pointer_cast<ContinuationState>(entry.object);
          std::lock_guard<std::mutex> continuation_lock(state->mutex);
          if (!state->finished && state->deadline <= now) expired.push_back(std::move(state));
        }
      }
      for (const auto& state : expired) FinishContinuation(state, state->default_action, L"{}");
    }
  });
}

void StopContinuationTimer() {
  if (!g_continuation_timer) return;
  g_continuation_timer->request_stop();
  g_continuation_timer.reset();
}

std::wstring OperationInfoJson(const Cef3OperationDescriptorV4& entry) {
  std::wostringstream json;
  json << L"{\"operationId\":\"0x" << std::hex << std::setw(16) << std::setfill(L'0')
       << entry.operation_id << std::dec
       << L"\",\"functionId\":\"" << JsonEscape(entry.function_id)
       << L"\",\"moduleId\":\"" << JsonEscape(entry.module_id)
       << L"\",\"chineseName\":\"" << JsonEscape(entry.chinese_name)
       << L"\",\"officialName\":\"" << JsonEscape(entry.official_name)
       << L"\",\"inputCodecs\":\"" << JsonEscape(entry.input_codecs)
       << L"\",\"outputCodec\":\"" << JsonEscape(entry.output_codec)
       << L"\",\"thread\":\"" << JsonEscape(entry.thread)
       << L"\",\"execution\":\"" << JsonEscape(entry.execution)
       << L"\",\"ownership\":\"" << JsonEscape(entry.ownership)
       << L"\",\"implementationStatus\":\"" << JsonEscape(entry.implementation_status)
       << L"\",\"publicSurface\":" << (entry.public_surface ? L"true" : L"false") << L"}";
  return json.str();
}

bool ValidateV4Argument(const LB_CEF3_CALL_V4* call, size_t index, uint32_t kind) {
  return call && index < call->argument_count && call->arguments
      && call->arguments[index].struct_size >= sizeof(LB_CEF3_ARGUMENT_V4)
      && call->arguments[index].value_kind == kind;
}

bool IsValidSwitchName(const wchar_t* name) {
  if (!name || !*name) return false;
  for (const wchar_t* cursor = name; *cursor; ++cursor) {
    if (*cursor < 0x21 || *cursor > 0x7e || *cursor == L'=') return false;
  }
  return true;
}

std::wstring QuoteWindowsCommandLineArgument(const std::wstring& argument) {
  if (!argument.empty() && argument.find_first_of(L" \t\"") == std::wstring::npos) return argument;
  std::wstring quoted(1, L'"');
  size_t backslashes = 0;
  for (wchar_t ch : argument) {
    if (ch == L'\\') {
      ++backslashes;
      continue;
    }
    if (ch == L'"') {
      quoted.append(backslashes * 2 + 1, L'\\');
      quoted.push_back(L'"');
    } else {
      quoted.append(backslashes, L'\\');
      quoted.push_back(ch);
    }
    backslashes = 0;
  }
  quoted.append(backslashes * 2, L'\\');
  quoted.push_back(L'"');
  return quoted;
}

int ReadCommandLineArgumentList(LB_CEF3_HANDLE arguments, std::vector<std::wstring>& values) {
  int status = 0;
  auto state = GetListState(arguments, status);
  if (!state) return status;
  std::lock_guard<std::mutex> lock(state->mutex);
  if (!state->value || !state->value->IsValid())
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF命令行参数列表无效");
  const size_t size = state->value->GetSize();
  if (size == 0)
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"命令行参数数组必须包含程序名");
  values.reserve(size);
  for (size_t index = 0; index < size; ++index) {
    if (state->value->GetType(index) != VTYPE_STRING)
      return Fail(LB_CEF3_ERROR_HANDLE_TYPE, L"命令行参数数组只能包含文本");
    values.push_back(state->value->GetString(index).ToWString());
  }
  if (values.front().empty())
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"命令行参数数组首项必须是非空程序名");
  return LB_CEF3_OK;
}

template <typename T>
bool ValidateViewsStruct(const T* value, const wchar_t* description) {
  if (!value || value->struct_size < sizeof(T)
      || value->abi_version != LB_CEF3_ABI_VERSION_V3) {
    Fail(LB_CEF3_ERROR_INVALID_ARGUMENT,
         std::wstring(description) + L"结构大小或ABI版本无效");
    return false;
  }
  return true;
}

std::shared_ptr<ViewState> SnapshotManagedView(
    LB_CEF3_HANDLE handle, CefRefPtr<CefView>& view, int& status) {
  auto state = GetViewState(handle, status);
  if (!state) return {};
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    view = state->view;
  }
  if (!view) {
    status = Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"CEF View对象已经释放");
    return {};
  }
  status = LB_CEF3_OK;
  return state;
}

int InvokeViewOnUi(LB_CEF3_HANDLE handle,
                   const std::function<void(CefRefPtr<CefView>)>& action,
                   bool require_valid = true) {
  int status = 0;
  CefRefPtr<CefView> view;
  auto state = SnapshotManagedView(handle, view, status);
  if (!state) return status;
  bool invalid = false;
  if (!RunOnCefUiSync([&]() {
        if (require_valid && !view->IsValid()) {
          invalid = true;
          return;
        }
        action(view);
      })) {
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"无法调度到CEF UI线程");
  }
  if (invalid) return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF View对象已经失效");
  return LB_CEF3_OK;
}

int InvokeViewDelegateOnUi(
    LB_CEF3_HANDLE delegate_handle, LB_CEF3_HANDLE view_handle,
    const std::function<void(CefRefPtr<CefViewDelegate>, CefRefPtr<CefView>)>& action) {
  int delegate_status = 0;
  auto delegate_state = GetViewDelegateState(delegate_handle, delegate_status);
  if (!delegate_state) return delegate_status;
  CefRefPtr<CefViewDelegate> delegate = delegate_state->delegate;
  if (!delegate) {
    return Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"CEF ViewDelegate对象已经释放");
  }

  int view_status = 0;
  CefRefPtr<CefView> view;
  auto view_state = SnapshotManagedView(view_handle, view, view_status);
  if (!view_state) return view_status;
  bool invalid = false;
  if (!RunOnCefUiSync([&]() {
        if (!view->IsValid()) {
          invalid = true;
          return;
        }
        action(delegate, view);
      })) {
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"无法调度到CEF UI线程");
  }
  if (invalid) return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"CEF View对象已经失效");
  return LB_CEF3_OK;
}

int ConvertViewHandle(
    LB_CEF3_HANDLE handle, LB_CEF3_HANDLE* result,
    const std::function<CefRefPtr<CefView>(CefRefPtr<CefView>)>& convert,
    int result_type = LB_CEF3_HANDLE_VIEW) {
  if (!result) return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"View输出句柄不能为空");
  *result = 0;
  CefRefPtr<CefView> converted;
  const int status = InvokeViewOnUi(handle, [&](CefRefPtr<CefView> view) {
    converted = convert(view);
  });
  if (status != LB_CEF3_OK || !converted) return status;
  *result = RegisterView(std::move(converted), result_type);
  return *result ? LB_CEF3_OK : LB_CEF3_ERROR_OPERATION_FAILED;
}

