constexpr size_t kMaximumDraggableRegionCount = 65536;
constexpr size_t kMaximumCompositionUnderlineCount = 4096;

int ReadManagedDraggableRegions(
    LB_CEF3_HANDLE regions, std::vector<CefDraggableRegion>& result) {
  int status = 0;
  auto state = GetListState(regions, status);
  if (!state) return status;
  std::lock_guard<std::mutex> lock(state->mutex);
  if (!state->value || !state->value->IsValid())
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"受管拖拽区域列表已经失效");
  const size_t size = state->value->GetSize();
  if (size > kMaximumDraggableRegionCount)
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"受管拖拽区域超过安全数量限制");
  std::vector<CefDraggableRegion> parsed;
  parsed.reserve(size);
  for (size_t index = 0; index < size; ++index) {
    if (state->value->GetType(index) != VTYPE_DICTIONARY)
      return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"拖拽区域元素必须是字典");
    const auto item = state->value->GetDictionary(index);
    if (!item || !item->IsValid() || item->GetSize() != 5
        || item->GetType(L"x") != VTYPE_INT
        || item->GetType(L"y") != VTYPE_INT
        || item->GetType(L"width") != VTYPE_INT
        || item->GetType(L"height") != VTYPE_INT
        || item->GetType(L"draggable") != VTYPE_BOOL) {
      return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT,
                  L"拖拽区域必须只包含x、y、width、height整数和draggable逻辑字段");
    }
    const int width = item->GetInt(L"width");
    const int height = item->GetInt(L"height");
    if (width < 0 || height < 0)
      return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"拖拽区域宽高不能为负数");
    CefDraggableRegion region;
    region.bounds = CefRect(
        item->GetInt(L"x"), item->GetInt(L"y"), width, height);
    region.draggable = item->GetBool(L"draggable");
    parsed.push_back(region);
  }
  result = std::move(parsed);
  return LB_CEF3_OK;
}

int ReadManagedCompositionUnderlines(
    LB_CEF3_HANDLE underlines,
    std::vector<LB_CEF3_COMPOSITION_UNDERLINE_V3>& result) {
  int status = 0;
  auto state = GetListState(underlines, status);
  if (!state) return status;
  std::lock_guard<std::mutex> lock(state->mutex);
  if (!state->value || !state->value->IsValid())
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"受管IME下划线列表已经失效");
  const size_t size = state->value->GetSize();
  if (size > kMaximumCompositionUnderlineCount)
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"IME下划线数量超过Bridge安全限制");
  std::vector<LB_CEF3_COMPOSITION_UNDERLINE_V3> parsed;
  parsed.reserve(size);
  for (size_t index = 0; index < size; ++index) {
    if (state->value->GetType(index) != VTYPE_DICTIONARY)
      return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"IME下划线元素必须是字典");
    const auto item = state->value->GetDictionary(index);
    if (!item || !item->IsValid() || item->GetSize() != 6
        || item->GetType(L"from") != VTYPE_INT
        || item->GetType(L"to") != VTYPE_INT
        || item->GetType(L"color") != VTYPE_INT
        || item->GetType(L"backgroundColor") != VTYPE_INT
        || item->GetType(L"thick") != VTYPE_BOOL
        || item->GetType(L"style") != VTYPE_INT) {
      return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT,
                  L"IME下划线必须只包含from、to、color、backgroundColor、thick和style字段");
    }
    const int from = item->GetInt(L"from");
    const int to = item->GetInt(L"to");
    const int style = item->GetInt(L"style");
    if (from < 0 || to < from || style < CEF_CUS_SOLID || style >= CEF_CUS_NUM_VALUES)
      return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"IME下划线范围或样式无效");
    parsed.push_back({
        sizeof(LB_CEF3_COMPOSITION_UNDERLINE_V3), LB_CEF3_ABI_VERSION_V3,
        {sizeof(LB_CEF3_RANGE_V3), LB_CEF3_ABI_VERSION_V3,
         static_cast<uint32_t>(from), static_cast<uint32_t>(to)},
        static_cast<uint32_t>(item->GetInt(L"color")),
        static_cast<uint32_t>(item->GetInt(L"backgroundColor")),
        item->GetBool(L"thick") ? 1 : 0, style});
  }
  result = std::move(parsed);
  return LB_CEF3_OK;
}

bool IsPdfPrintBoolean(int32_t value) {
  return value == 0 || value == 1;
}

bool ValidatePdfPrintNumbers(const CefPdfPrintSettings& settings) {
  const std::array<double, 7> values{
      settings.scale, settings.paper_width, settings.paper_height,
      settings.margin_top, settings.margin_right,
      settings.margin_bottom, settings.margin_left};
  return std::all_of(values.begin(), values.end(), [](double value) {
    return std::isfinite(value);
  }) && (settings.margin_type != PDF_PRINT_MARGIN_CUSTOM
      || (settings.margin_top >= 0.0 && settings.margin_right >= 0.0
          && settings.margin_bottom >= 0.0 && settings.margin_left >= 0.0));
}

int ConvertPdfPrintSettings(
    const LB_CEF3_PDF_PRINT_SETTINGS_V3* source,
    CefPdfPrintSettings& result) {
  if (!ValidateViewsStruct(source, L"PDF打印设置")
      || !IsPdfPrintBoolean(source->landscape)
      || !IsPdfPrintBoolean(source->print_background)
      || !IsPdfPrintBoolean(source->prefer_css_page_size)
      || !IsPdfPrintBoolean(source->display_header_footer)
      || !IsPdfPrintBoolean(source->generate_tagged_pdf)
      || !IsPdfPrintBoolean(source->generate_document_outline)
      || source->margin_type < PDF_PRINT_MARGIN_DEFAULT
      || source->margin_type > PDF_PRINT_MARGIN_CUSTOM) {
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"PDF打印设置结构、逻辑值或边距类型无效");
  }
  result.landscape = source->landscape;
  result.print_background = source->print_background;
  result.scale = source->scale;
  result.paper_width = source->paper_width;
  result.paper_height = source->paper_height;
  result.prefer_css_page_size = source->prefer_css_page_size;
  result.margin_type = static_cast<cef_pdf_print_margin_type_t>(source->margin_type);
  result.margin_top = source->margin_top;
  result.margin_right = source->margin_right;
  result.margin_bottom = source->margin_bottom;
  result.margin_left = source->margin_left;
  CefString(&result.page_ranges) = source->page_ranges ? source->page_ranges : L"";
  result.display_header_footer = source->display_header_footer;
  CefString(&result.header_template) = source->header_template ? source->header_template : L"";
  CefString(&result.footer_template) = source->footer_template ? source->footer_template : L"";
  result.generate_tagged_pdf = source->generate_tagged_pdf;
  result.generate_document_outline = source->generate_document_outline;
  if (!ValidatePdfPrintNumbers(result))
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"PDF打印小数必须有限且自定义边距不能为负");
  return LB_CEF3_OK;
}

int ReadManagedPdfPrintSettings(
    LB_CEF3_HANDLE settings, CefPdfPrintSettings& result) {
  int status = 0;
  auto state = GetDictionaryState(settings, status);
  if (!state) return status;
  std::lock_guard<std::mutex> lock(state->mutex);
  if (!state->value || !state->value->IsValid())
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"受管PDF打印设置已经失效");
  const auto value = state->value;
  size_t recognized = 0;
  int margin_type = static_cast<int>(result.margin_type);
  const auto read_bool = [&](const wchar_t* key, int& target) {
    if (!value->HasKey(key)) return true;
    ++recognized;
    if (value->GetType(key) != VTYPE_BOOL) return false;
    target = value->GetBool(key) ? 1 : 0;
    return true;
  };
  const auto read_int = [&](const wchar_t* key, int& target) {
    if (!value->HasKey(key)) return true;
    ++recognized;
    if (value->GetType(key) != VTYPE_INT) return false;
    target = value->GetInt(key);
    return true;
  };
  const auto read_double = [&](const wchar_t* key, double& target) {
    if (!value->HasKey(key)) return true;
    ++recognized;
    const auto type = value->GetType(key);
    if (type != VTYPE_DOUBLE && type != VTYPE_INT) return false;
    target = type == VTYPE_DOUBLE ? value->GetDouble(key) : value->GetInt(key);
    return std::isfinite(target);
  };
  const auto read_string = [&](const wchar_t* key, cef_string_t& target) {
    if (!value->HasKey(key)) return true;
    ++recognized;
    if (value->GetType(key) != VTYPE_STRING) return false;
    CefString target_string(&target);
    target_string = value->GetString(key);
    return true;
  };
  if (!read_bool(L"landscape", result.landscape)
      || !read_bool(L"printBackground", result.print_background)
      || !read_double(L"scale", result.scale)
      || !read_double(L"paperWidth", result.paper_width)
      || !read_double(L"paperHeight", result.paper_height)
      || !read_bool(L"preferCssPageSize", result.prefer_css_page_size)
      || !read_int(L"marginType", margin_type)
      || !read_double(L"marginTop", result.margin_top)
      || !read_double(L"marginRight", result.margin_right)
      || !read_double(L"marginBottom", result.margin_bottom)
      || !read_double(L"marginLeft", result.margin_left)
      || !read_string(L"pageRanges", result.page_ranges)
      || !read_bool(L"displayHeaderFooter", result.display_header_footer)
      || !read_string(L"headerTemplate", result.header_template)
      || !read_string(L"footerTemplate", result.footer_template)
      || !read_bool(L"generateTaggedPdf", result.generate_tagged_pdf)
      || !read_bool(L"generateDocumentOutline", result.generate_document_outline)
      || recognized != value->GetSize()
      || margin_type < PDF_PRINT_MARGIN_DEFAULT
      || margin_type > PDF_PRINT_MARGIN_CUSTOM) {
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT,
                L"受管PDF打印设置包含未知字段、错误类型或非法值");
  }
  result.margin_type = static_cast<cef_pdf_print_margin_type_t>(margin_type);
  if (!ValidatePdfPrintNumbers(result))
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"受管PDF打印设置包含非法小数或边距");
  return LB_CEF3_OK;
}

LB_CEF3_TASK_HANDLE StartBrowserPrintToPdf(
    LB_CEF3_HANDLE browser, const wchar_t* path,
    CefPdfPrintSettings settings) {
  std::filesystem::path resolved;
  if (!IsPathAllowed(path, resolved)) return 0;
  int status = 0;
  auto browser_state = GetBrowserState(browser, status);
  if (!browser_state) return 0;
  auto browser_ref = SnapshotBrowser(browser_state);
  if (!browser_ref || !browser_ref->GetHost()) {
    Fail(LB_CEF3_ERROR_OPERATION_FAILED,
         L"CEF3 browser is not ready or has already closed");
    return 0;
  }
  std::error_code error;
  std::filesystem::create_directories(resolved.parent_path(), error);
  if (error) {
    Fail(LB_CEF3_ERROR_OPERATION_FAILED,
         L"Unable to create the PDF output directory");
    return 0;
  }
  auto [task_handle, task_state] = CreateRunningTask();
  task_state->cef_backed.store(true, std::memory_order_release);
  if (!PostToCefUi([browser_ref, task_state, resolved,
                    settings = std::move(settings)]() mutable {
        auto host = browser_ref->GetHost();
        if (!host) {
          CompleteTask(task_state, false,
                       L"CEF3 browser host is unavailable for PDF printing");
          return;
        }
        CefRefPtr<CefPdfPrintCallback> callback =
            new BridgePdfPrintCallback(task_state);
        host->PrintToPDF(resolved.wstring(), settings, callback);
      })) {
    CompleteTask(task_state, false, L"Unable to dispatch PDF printing to CEF UI");
  }
  return task_handle;
}

