int RetainManagedBrowserFor(
    CefRefPtr<CefBrowser> browser, LB_CEF3_HANDLE* result) {
  if (!result)
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT,
                L"Managed Browser output cannot be null");
  *result = 0;
  if (!browser) return LB_CEF3_OK;
  std::vector<std::pair<LB_CEF3_HANDLE, std::shared_ptr<BrowserState>>> candidates;
  {
    std::lock_guard<std::mutex> lock(g_mutex);
    candidates.reserve(g_browser_states.size());
    for (const auto& item : g_browser_states) {
      if (auto state = item.second.lock())
        candidates.emplace_back(item.first, std::move(state));
    }
  }
  const int browser_id = browser->GetIdentifier();
  for (const auto& candidate : candidates) {
    const auto managed_browser = SnapshotBrowser(candidate.second);
    if (managed_browser && managed_browser->GetIdentifier() == browser_id)
      return RetainBrowserAlias(candidate.first, result);
  }
  return Fail(LB_CEF3_ERROR_NOT_FOUND,
              L"BrowserView browser is not owned by this Bridge");
}

int ReadManagedBrowserViewSettings(
    LB_CEF3_HANDLE settings, uint32_t& flags) {
  int status = 0;
  auto state = GetDictionaryState(settings, status);
  if (!state) return status;
  std::lock_guard<std::mutex> lock(state->mutex);
  if (!state->value || !state->value->IsValid())
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED,
                L"Managed BrowserView settings are invalid");
  flags = LB_CEF3_BROWSER_JAVASCRIPT | LB_CEF3_BROWSER_IMAGES
      | LB_CEF3_BROWSER_WEBGL;
  size_t recognized = 0;
  const auto read = [&](const wchar_t* key, uint32_t flag) {
    if (!state->value->HasKey(key)) return true;
    ++recognized;
    if (state->value->GetType(key) != VTYPE_BOOL) return false;
    if (state->value->GetBool(key)) flags |= flag;
    else flags &= ~flag;
    return true;
  };
  if (!read(L"javascript", LB_CEF3_BROWSER_JAVASCRIPT)
      || !read(L"images", LB_CEF3_BROWSER_IMAGES)
      || !read(L"webgl", LB_CEF3_BROWSER_WEBGL)
      || recognized != state->value->GetSize()) {
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT,
                L"BrowserView settings only accept boolean javascript, images and webgl fields");
  }
  return LB_CEF3_OK;
}

