std::shared_ptr<ControlViewDelegateConfiguration>
GetControlViewDelegateConfiguration(
    LB_CEF3_HANDLE handle, uint32_t required_kind, int& status) {
  auto state = GetViewDelegateState(handle, status);
  if (!state) return {};
  const bool matches =
      (required_kind == kControlDelegateTextfieldKeyEvent
       || required_kind == kControlDelegateTextfieldAfterUserAction)
          ? static_cast<bool>(state->textfield_delegate)
          : required_kind == kControlDelegateMenuButtonPressed
              ? static_cast<bool>(state->menu_button_delegate)
              : static_cast<bool>(state->button_delegate);
  if (!matches || !state->control_configuration) {
    status = Fail(
        LB_CEF3_ERROR_HANDLE_TYPE,
        L"ViewDelegate句柄与请求的控件委托类型不匹配");
    return {};
  }
  status = LB_CEF3_OK;
  return state->control_configuration;
}

