      int status = LB_CEF3_OK;
      if (call->operation_id == UINT64_C(0x8567ecf6d420f4d0))
        status = LB_CEF3_ServerNextDestroyed(call->target, &task);
      else if (call->operation_id == UINT64_C(0x50517dc78b9cd7d2))
        status = LB_CEF3_ServerNextClientConnected(call->target, &task);
      else if (call->operation_id == UINT64_C(0x36ade245b38e848e))
        status = LB_CEF3_ServerNextClientDisconnected(call->target, &task);
      else if (call->operation_id == UINT64_C(0xd18dec73ebba261f))
        status = LB_CEF3_ServerNextHttpRequest(call->target, &task);
      else if (call->operation_id == UINT64_C(0xdc55b39bd5e58581))
        status = LB_CEF3_ServerNextWebSocketRequest(call->target, &task);
      else if (call->operation_id == UINT64_C(0xa980426c1b5d73a2))
        status = LB_CEF3_ServerNextWebSocketConnected(call->target, &task);
      else
        status = LB_CEF3_ServerNextWebSocketMessage(call->target, &task);
