int SetRenderProcessHandlerSubscription(
    LB_CEF3_HANDLE browser, uint32_t subscription, int enabled) {
  if (enabled != 0 && enabled != 1) {
    return Fail(
        LB_CEF3_ERROR_INVALID_ARGUMENT,
        L"渲染进程处理器订阅开关必须是0或1");
  }
  int status = LB_CEF3_OK;
  auto state = GetBrowserState(browser, status);
  if (!state) return status;
  bool replay_webkit_initialized = false;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (state->closed) {
      return Fail(
          LB_CEF3_ERROR_OPERATION_FAILED,
          L"浏览器已经关闭，无法修改渲染进程处理器订阅");
    }
    if (enabled != 0) {
      state->render_process_handler_subscriptions |= subscription;
      replay_webkit_initialized =
          subscription == kRenderProcessHandlerWebKitInitialized
          && state->render_process_webkit_initialized;
    } else {
      state->render_process_handler_subscriptions &= ~subscription;
    }
  }
  if (replay_webkit_initialized) {
    EmitRenderProcessHandlerNotification(
        state, kRenderProcessHandlerWebKitInitialized,
        L"on_web_kit_initialized", L"渲染进程 WebKit 已初始化", L"{}");
  }
  return LB_CEF3_OK;
}

