  int status = 0;
  auto state = GetImageState(image, status);
  if (!state) return 0;
  struct BinaryResult { CefRefPtr<CefBinaryValue> binary; int width = 0; int height = 0; };
  auto output = std::make_shared<BinaryResult>();
