  if (!RunOnCefUiSync([&]() { value = read(state->sink).ToWString(); }))
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED,
                L"Unable to dispatch MediaSink text query to CEF UI");
  return CopyWide(value, result, capacity, required);
