  CefRefPtr<CefCompletionCallback> callback = new BridgeCompletionCallback(task_state, L"{\"flushed\":true}");
  if (!manager->FlushStore(callback)) CompleteTask(task_state, false, L"提交Cookie落盘失败");
  return task;
