  std::lock_guard<std::mutex> lock(state->mutex);
  if (!state->request) return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"请求对象已经失效");
  if (state->request->IsReadOnly()) {
    return Fail(LB_CEF3_ERROR_OPERATION_FAILED, L"只读请求不能修改头字段");
  }
  state->request->SetHeaderByName(name, value, overwrite != 0);
