int InvokeBoxLayoutViewOperation(
    LB_CEF3_HANDLE layout_handle, LB_CEF3_HANDLE view_handle,
    const std::function<void(CefRefPtr<CefBoxLayout>, CefRefPtr<CefView>)>& action) {
  int view_status = 0;
  CefRefPtr<CefView> view;
  auto view_state = SnapshotManagedView(view_handle, view, view_status);
  if (!view_state) return view_status;
  int layout_status = 0;
  auto layout_state = GetLayoutState(layout_handle, layout_status);
  if (!layout_state) return layout_status;
  CefRefPtr<CefPanel> owner;
  {
    std::lock_guard<std::mutex> lock(layout_state->mutex);
    owner = layout_state->owner_panel;
  }
  bool not_box = false;
  bool invalid_view = false;
  const int status = InvokeLayoutOnUi(layout_handle, [&](CefRefPtr<CefLayout> layout) {
    auto box = layout->AsBoxLayout();
    const auto parent = view->IsValid() ? view->GetParentView() : nullptr;
    if (!box) {
      not_box = true;
      return;
    }
    if (!owner || !parent || !owner->IsSame(parent)) {
      invalid_view = true;
      return;
    }
    action(box, view);
  });
  if (status != LB_CEF3_OK) return status;
  if (not_box) return Fail(LB_CEF3_ERROR_HANDLE_TYPE, L"Layout句柄不是BoxLayout");
  if (invalid_view)
    return Fail(LB_CEF3_ERROR_INVALID_ARGUMENT, L"View不是该BoxLayout所属Panel的直接子项");
  return LB_CEF3_OK;
}

