int ConvertDisplayPoint(
    LB_CEF3_HANDLE display, LB_CEF3_POINT_V3* point, bool to_pixels) {
  if (!ValidateViewsStruct(point, L"显示器转换点"))
    return LB_CEF3_ERROR_INVALID_ARGUMENT;
  CefPoint value(point->x, point->y);
  const int status = InvokeDisplayOnUi(display, [&](CefRefPtr<CefDisplay> item) {
    if (to_pixels) item->ConvertPointToPixels(value);
    else item->ConvertPointFromPixels(value);
  });
  if (status == LB_CEF3_OK) {
    point->x = value.x;
    point->y = value.y;
  }
  return status;
}

