int ReadDragDataText(
    LB_CEF3_HANDLE drag_data, wchar_t* result, size_t capacity, size_t* required,
    const std::function<CefString(CefRefPtr<CefDragData>)>& read) {
  int status = 0;
  auto state = GetDragDataState(drag_data, status);
  if (!state) return status;
  std::wstring value;
  {
    std::lock_guard<std::mutex> lock(state->mutex);
    if (!state->drag_data)
      return Fail(LB_CEF3_ERROR_RELEASED_HANDLE, L"CEF DragData对象已经释放");
    value = read(state->drag_data).ToWString();
  }
  return CopyWide(value, result, capacity, required);
}

